import { Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from '../../../../../../shared/components/icon/icon.component';
import { annotTypes } from '../../../../../interfaces/annotation.interface';

@Component({
  selector: 'annot-icon',
  standalone: true,
  imports: [IconComponent],
  templateUrl: './annot-icon.component.html',
  styleUrl: './annot-icon.component.scss'
})
export class AnnotIconComponent {
  @Input() isActive: boolean;
  @Input() color: string;
  @Input() id: string;
  @Input() type: annotTypes;

  @Output() iconClickEvent: EventEmitter<{ type: annotTypes, id: string }> = new EventEmitter<{ type: annotTypes, id: string }>()


  iconClick() {
    this.iconClickEvent?.emit({ type: this.type, id: this.id });
  }

}
