import {
  Component, Input, Output, EventEmitter, OnChanges, SimpleChanges,
  ChangeDetectionStrategy, ElementRef, ViewChild, NgZone, OnDestroy
} from '@angular/core';
import { CommonModule } from '@angular/common';

/**
 * Custom vertical scrollbar rendered right next to the transcript content.
 *
 * Mirrors the native scrollbar behaviour (smooth dragging, track click,
 * arrow buttons) but is rendered as a visible UI element at a controlled
 * position instead of relying on the browser's own scrollbar which sits
 * at the far right edge of the window.
 *
 * The host feed-display component pushes scroll-state updates via inputs
 * and reacts to the `scrollTo` output to drive the CDK virtual viewport.
 */
@Component({
  selector: 'scroll-markers',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './scroll-markers.component.html',
  styleUrl: './scroll-markers.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ScrollMarkersComponent implements OnChanges, OnDestroy {
  /** Current scrollTop of the virtual-scroll viewport (px). */
  @Input() scrollTop: number = 0;
  /** Total scrollHeight of the virtual-scroll viewport (px). */
  @Input() scrollHeight: number = 1;
  /** Visible clientHeight of the virtual-scroll viewport (px). */
  @Input() clientHeight: number = 1;

  /** Emitted when the user clicks the track, drags the thumb, or
   *  presses an arrow button. Value = desired scrollTop (px). */
  @Output() scrollTo = new EventEmitter<number>();

  @ViewChild('track', { static: false }) trackRef!: ElementRef<HTMLElement>;

  /** Thumb top position as a percentage (0–100). */
  thumbTop: number = 0;
  /** Thumb height as a percentage (clamped ≥ 3%). */
  thumbHeight: number = 100;

  private dragging = false;
  /** Y offset within the thumb where the drag started. */
  private dragOffsetY = 0;
  private boundMouseMove: (e: MouseEvent) => void;
  private boundMouseUp: () => void;

  constructor(private ngZone: NgZone) {
    this.boundMouseMove = this.onDocMouseMove.bind(this);
    this.boundMouseUp = this.onDocMouseUp.bind(this);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['scrollTop'] || changes['scrollHeight'] || changes['clientHeight']) {
      this.recalcThumb();
    }
  }

  ngOnDestroy(): void {
    document.removeEventListener('mousemove', this.boundMouseMove);
    document.removeEventListener('mouseup', this.boundMouseUp);
  }

  // ── Arrow buttons (scroll by ~one viewport height) ─────────────
  scrollUp(): void {
    const step = this.clientHeight * 0.85;
    this.scrollTo.emit(Math.max(0, this.scrollTop - step));
  }

  scrollDown(): void {
    const maxScroll = Math.max(0, this.scrollHeight - this.clientHeight);
    const step = this.clientHeight * 0.85;
    this.scrollTo.emit(Math.min(maxScroll, this.scrollTop + step));
  }

  // ── Track click → jump proportionally ──────────────────────────
  onTrackClick(event: MouseEvent): void {
    if (!this.trackRef) return;
    const rect = this.trackRef.nativeElement.getBoundingClientRect();
    const pct = (event.clientY - rect.top) / rect.height;
    const maxScroll = Math.max(0, this.scrollHeight - this.clientHeight);
    this.scrollTo.emit(Math.max(0, Math.min(maxScroll, pct * this.scrollHeight - this.clientHeight / 2)));
  }

  // ── Thumb drag ─────────────────────────────────────────────────
  onThumbMouseDown(event: MouseEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.dragging = true;

    // Remember where inside the thumb the user grabbed so the thumb
    // doesn't jump on first move.
    const thumbEl = event.currentTarget as HTMLElement;
    this.dragOffsetY = event.clientY - thumbEl.getBoundingClientRect().top;

    this.ngZone.runOutsideAngular(() => {
      document.addEventListener('mousemove', this.boundMouseMove);
      document.addEventListener('mouseup', this.boundMouseUp);
    });
  }

  private onDocMouseMove(event: MouseEvent): void {
    if (!this.dragging || !this.trackRef) return;
    const trackRect = this.trackRef.nativeElement.getBoundingClientRect();
    const trackH = trackRect.height;
    if (trackH <= 0) return;

    // Thumb top in track-relative pixels
    const thumbTopPx = event.clientY - trackRect.top - this.dragOffsetY;
    // Usable range: the thumb can travel from 0 to (trackH - thumbHeightPx)
    const thumbHeightPx = (this.thumbHeight / 100) * trackH;
    const maxThumbTop = trackH - thumbHeightPx;
    const clampedTop = Math.max(0, Math.min(maxThumbTop, thumbTopPx));
    const pct = maxThumbTop > 0 ? clampedTop / maxThumbTop : 0;
    const maxScroll = Math.max(0, this.scrollHeight - this.clientHeight);
    const target = pct * maxScroll;

    this.ngZone.run(() => this.scrollTo.emit(target));
  }

  private onDocMouseUp(): void {
    this.dragging = false;
    document.removeEventListener('mousemove', this.boundMouseMove);
    document.removeEventListener('mouseup', this.boundMouseUp);
  }

  // ── Helpers ────────────────────────────────────────────────────
  private recalcThumb(): void {
    if (this.scrollHeight <= 0 || this.clientHeight <= 0) {
      this.thumbTop = 0;
      this.thumbHeight = 100;
      return;
    }
    // Thumb height proportional to visible fraction, min 3%
    this.thumbHeight = Math.max(3, (this.clientHeight / this.scrollHeight) * 100);

    // Thumb position
    const maxScroll = this.scrollHeight - this.clientHeight;
    const scrollPct = maxScroll > 0 ? this.scrollTop / maxScroll : 0;
    // Thumb can travel from 0% to (100% - thumbHeight%)
    this.thumbTop = scrollPct * (100 - this.thumbHeight);
  }
}
