import { feedAnnotations, feedAnnotCordinates } from "../../../../../interfaces/annotation.interface";

export class iconLayer {
    // { y: number; height: number }
    updateIcon(rectangles: feedAnnotCordinates[]): { lowest: number; highest: number; difference: number } { //, firstrefrence, highestY
        const rects = rectangles?.filter(a => a.y) || []
        if (rects.length === 0) {
            return { lowest: 0, highest: 0, difference: 0 };
        }
        let { lowest, highest } = rects?.reduce((acc, rect) => ({
            lowest: Math.min(acc.lowest, rect.y),
            highest: Math.max(acc.highest, rect.y)
        }), { lowest: rects[0].y, highest: rects[0].y });

        let difference = (highest - lowest) + rects[0].height;
        // if (rects.length === 1) {
        //     lowest = lowest - 30;
        // }
        if (difference < 60) {
            difference = 60;
        }
        return { lowest, highest, difference };
    }


    iconPosition(annotation: feedAnnotations): { iconY: number, iconHeight: number } {
        const iconVal = this.updateIcon(annotation.jCordinates);
        // Use actual coordinate span instead of hardcoded lineHeight * count
        // so the icon covers wrapped lines correctly.
        let totalLineHeight = iconVal.difference;
        if (totalLineHeight < 60) totalLineHeight = 60;
        return { iconHeight: totalLineHeight, iconY: iconVal.lowest }
    }

    elementLoad(e, annotation: feedAnnotations) {
        const iconVal = this.updateIcon(annotation.jCordinates);
        e.setAttribute('y', iconVal.lowest)


        const originalLength = annotation.jCordinates?.length;
        const updatedLength = annotation.jCordinates?.length;

        const lineHeight = 24;
        let totalLineHeight = annotation.jCordinates?.length * lineHeight;
        if (updatedLength != originalLength) {
            try {
                const remainLength = originalLength - updatedLength;
                const pageSpaces = (Math.floor((remainLength - 1) / 25) + 1)
                totalLineHeight += (pageSpaces * 75)
            } catch (error) {

            }
        }
        e.setAttribute('height', totalLineHeight > 60 ? totalLineHeight : 60)
        // , iconVal.difference + (annotation?.pageCount && annotation?.pageCount > 1 ? (annotation.pageCount - 1) * 84 : 0)
    }
}