import { Component, ChangeDetectorRef, DestroyRef, ElementRef, inject, Input, SimpleChanges } from '@angular/core';
import { feedAnnotations, feedAnnotCordinates } from '../../../../../interfaces/annotation.interface';
import { finalFeedData } from '../../../../../interfaces/feed-display.interface';
import { FeedUtilityService } from '../../../../../services/feed-utility/feed-utility.service';
import { ListRange } from '@angular/cdk/collections';
import { NgStyle } from '@angular/common';
import { AnnotIconComponent } from '../annot-icon/annot-icon.component';
import { InitDirective } from '../../../../../directives/init.directive';
import { iconLayer } from './icon-layer';
import { FeedDisplayService } from '../../../../../services/feed-display/feed-display.service';

@Component({
  selector: 'annotation-layer',
  standalone: true,
  imports: [NgStyle, AnnotIconComponent, InitDirective],
  templateUrl: './annotation-layer.component.html',
  styleUrl: './annotation-layer.component.scss'
})
export class AnnotationLayerComponent extends iconLayer {
  @Input() lines: finalFeedData[] = [];
  @Input() annotations: feedAnnotations[] = []
  @Input() pageno: number;
  @Input() activeRange: ListRange;
  @Input() showTimestamp: boolean;

  @Input() visibleMarkNavModel: boolean;

  qFacts: feedAnnotations[] = []


  y_offset = 0;
  y_height = 24;

  base_width: number = 875 - 16;
  margin = -1;

  @Input() filterAnnots: string[] = [];
  private destroyRef = inject(DestroyRef);
  constructor(private readonly util: FeedUtilityService, private fds: FeedDisplayService, private el: ElementRef, private cdr: ChangeDetectorRef) {
    super()
  }

  ngOnInit(): void {
    this.renderAnnot();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["annotations"] && !changes["annotations"].firstChange) {
      this.renderAnnot();
    }

    if (changes["lines"] && !changes["lines"].firstChange) {
      this.renderAnnot();
    } else if (changes["filterAnnots"] && !changes["filterAnnots"].firstChange) {
      this.renderAnnot();
    }
  }

  // Called whenever this page becomes visible again in the viewport
  onVisible(): void {
    if (this.qFacts.length) {
      requestAnimationFrame(() => {
        this.measureCoordsFromDOM();
        this.cdr.detectChanges();
      });
    }
  }

  renderAnnot() {
    try {
      this.qFacts = [];
      if (this.lines?.length && this.annotations?.length) {
        const startTime = this.util.timeToFram(this.lines[0]?.time);
        const endTime = this.util.timeToFram(this.lines[this.lines.length - 1].time);

        const affectedAnnots = this.annotations.filter(a => a.jCordinates?.findIndex(b =>
          (this.util.timeToFram(b.t) >= startTime && endTime >= this.util.timeToFram(b.t)) ||
          (b.p == this.pageno)
        ) > -1);

        if (this.filterAnnots.length) {
          for (let x of affectedAnnots) {
            if (this.filterAnnots.includes(x.id))
              this.loadAnnot(x);
          }
        } else {
          for (let x of affectedAnnots) {
            this.loadAnnot(x);
          }
        }
      }
      // After building qFacts with placeholder coordinates, measure
      // the real positions from the DOM.  The sibling text-layer may
      // not have rendered yet, so retry a few times.
      if (this.qFacts.length) {
        const tryMeasure = (retriesLeft: number) => {
          requestAnimationFrame(() => {
            const ok = this.measureCoordsFromDOM();
            this.cdr.detectChanges();
            if (!ok && retriesLeft > 0) {
              setTimeout(() => tryMeasure(retriesLeft - 1), 60);
            }
          });
        };
        tryMeasure(4);

        // Second pass after fonts finish loading — text may reflow.
        document.fonts?.ready?.then(() => {
          requestAnimationFrame(() => {
            this.measureCoordsFromDOM();
            this.cdr.detectChanges();
          });
        });
      }
    } catch (error) {
      console.error(error);
    }
  }

  /**
   * Measure ALL annotation coordinates (x, y, width, height) directly
   * from the rendered DOM using the Range API.
   *
   * This replaces the old canvas-based measurement which suffered from:
   *  1) HTML entity mismatch (&emsp; = 6 chars in raw text vs 1 char in DOM)
   *  2) Canvas font metrics ≠ DOM font metrics
   *  3) Hardcoded pixel offsets for timestamps / line numbers
   *
   * By measuring from the actual rendered text, highlights are pixel-perfect.
   */
  private measureCoordsFromDOM(): boolean {
    if (!this.qFacts.length) return true;

    const container = this.el.nativeElement.parentElement;
    if (!container) return false;

    const containerRect = container.getBoundingClientRect();
    if (!containerRect.height) return false;

    // getBoundingClientRect returns post-zoom (visual) pixels, but the SVG
    // <rect> coords we write are in user units that the same CSS `zoom` will
    // scale a *second* time at render. Divide deltas by the cumulative
    // ancestor zoom so highlights stay aligned in the squeezed preview pane.
    // At zoom=1 (individual-doc), this is a no-op.
    const zoom = this.getEffectiveZoom(container);

    let allFound = true;

    for (const annot of this.qFacts) {
      const coords = annot.jCordinates as any[];
      const totalCoords = coords.length;

      for (let i = 0; i < totalCoords; i++) {
        const coord = coords[i];
        const isFirst = (i === 0);
        const isLast = (i === totalCoords - 1);
        const isOnly = (totalCoords === 1);

        const lineEl = container.querySelector(
          `.line[pno="${this.pageno}"][lno="${coord.l}"]`
        ) as HTMLElement;
        if (!lineEl) { allFound = false; continue; }

        const pre = lineEl.querySelector('pre') as HTMLElement;
        if (!pre) { allFound = false; continue; }

        const lineRect = lineEl.getBoundingClientRect();
        const relY = (lineRect.top - containerRect.top) / zoom;
        const lineH = lineRect.height / zoom;

        // Right edge of the text area (for extending first/middle lines)
        const lineTextDiv = lineEl.querySelector('.line-text') as HTMLElement;
        const textAreaRight = lineTextDiv
          ? (lineTextDiv.getBoundingClientRect().right - containerRect.left) / zoom
          : containerRect.width / zoom;

        // Collect text nodes from the <pre>
        const textNodes: Text[] = [];
        const walker = document.createTreeWalker(pre, NodeFilter.SHOW_TEXT);
        while (walker.nextNode()) textNodes.push(walker.currentNode as Text);

        if (!textNodes.length) { allFound = false; continue; }

        const fullVisibleText = textNodes.map(n => n.textContent).join('');

        // Middle lines of multi-line annotations: highlight full line
        if (!isFirst && !isLast) {
          this.setFullLineCoords(coord, textNodes, containerRect, relY, lineH, textAreaRight, zoom);
          continue;
        }

        // First / last / single-line: find the annotation text in DOM text
        const annotText = (coord.text || '').trim();
        const annotLower = annotText.toLowerCase();
        const visibleLower = fullVisibleText.toLowerCase();

        let matchStart = visibleLower.indexOf(annotLower);
        if (matchStart === -1 && annotLower.length > 0) {
          matchStart = this.fuzzyFindInText(annotLower, visibleLower);
        }

        if (matchStart === -1) {
          // Can't locate annotation text — fall back to full line
          this.setFullLineCoords(coord, textNodes, containerRect, relY, lineH, textAreaRight, zoom);
          continue;
        }

        const matchEnd = Math.min(matchStart + annotLower.length, fullVisibleText.length);

        let highlightStart: number;
        let highlightEnd: number;

        if (isOnly) {
          // Single-line annotation: highlight only the matched portion
          highlightStart = matchStart;
          highlightEnd = matchEnd;
        } else if (isFirst) {
          // First line: from match start to end of line
          highlightStart = matchStart;
          highlightEnd = fullVisibleText.length;
        } else {
          // Last line: from line start to match end
          highlightStart = 0;
          highlightEnd = matchEnd;
        }

        // Clamp
        highlightStart = Math.max(0, Math.min(highlightStart, fullVisibleText.length));
        highlightEnd = Math.max(highlightStart, Math.min(highlightEnd, fullVisibleText.length));

        // Map character indices to text node positions and create a Range
        const startPos = this.charIndexToNodeOffset(textNodes, highlightStart);
        const endPos = this.charIndexToNodeOffset(textNodes, highlightEnd);

        if (!startPos || !endPos) {
          this.setFullLineCoords(coord, textNodes, containerRect, relY, lineH, textAreaRight, zoom);
          continue;
        }

        const range = document.createRange();
        range.setStart(startPos.node, startPos.offset);
        range.setEnd(endPos.node, endPos.offset);
        const rangeRect = range.getBoundingClientRect();
        range.detach();

        let xStart = (rangeRect.left - containerRect.left) / zoom;
        let measuredWidth = rangeRect.width / zoom;

        // First line of multi-line: extend highlight to the text area edge
        if (isFirst && !isOnly) {
          measuredWidth = textAreaRight - xStart;
        }

        this.applyCoords(coord, xStart, relY, measuredWidth, lineH);
      }

      // Recalculate icon position with the measured Y values
      const iconObj = this.iconPosition(annot);
      if (iconObj) {
        (annot as any).iconY = iconObj.iconY;
        (annot as any).iconHeight = iconObj.iconHeight;
      }
    }

    return allFound;
  }

  /** Apply computed coordinates to a coordinate entry. */
  private applyCoords(coord: any, x: number, relY: number, width: number, lineH: number): void {
    if (coord.type === 'D') {
      // Dashed underline — sit near the text baseline
      const yLine = relY + this.margin + 11.5 + 10;
      coord.x = x;
      coord.y = yLine;
      coord.x2 = x + width;
      coord.y2 = yLine;
      coord.width = width;
      coord.height = 2;
    } else {
      coord.x = x;
      coord.y = relY + this.margin;
      coord.width = width;
      coord.height = lineH - 1;
    }
  }

  /** Set coords to cover the full line text area (for middle lines or fallback). */
  private setFullLineCoords(
    coord: any, textNodes: Text[], containerRect: DOMRect,
    relY: number, lineH: number, textAreaRight: number, zoom: number
  ): void {
    if (!textNodes.length) return;
    const range = document.createRange();
    range.setStart(textNodes[0], 0);
    const lastNode = textNodes[textNodes.length - 1];
    range.setEnd(lastNode, lastNode.textContent?.length || 0);
    const rangeRect = range.getBoundingClientRect();
    range.detach();

    const xStart = (rangeRect.left - containerRect.left) / zoom;
    const width = textAreaRight - xStart;
    this.applyCoords(coord, xStart, relY, width, lineH);
  }

  /**
   * Cumulative CSS `zoom` factor from `el` up to the document root. Returns 1
   * when no ancestor is zoomed (the individual-doc case). Used to convert
   * post-zoom visual pixel measurements (getBoundingClientRect) back to the
   * pre-zoom user units the SVG coordinate system expects.
   */
  private getEffectiveZoom(el: Element | null): number {
    let zoom = 1;
    let cur: Element | null = el;
    while (cur && cur !== document.documentElement) {
      const raw = (getComputedStyle(cur as HTMLElement) as any).zoom;
      const z = parseFloat(raw);
      if (z && isFinite(z) && z > 0) zoom *= z;
      cur = cur.parentElement;
    }
    return zoom > 0 ? zoom : 1;
  }

  /** Map a character index within the concatenated text to a specific text node + offset. */
  private charIndexToNodeOffset(textNodes: Text[], charIdx: number): { node: Text; offset: number } | null {
    let accumulated = 0;
    for (const node of textNodes) {
      const nodeLen = node.textContent?.length || 0;
      if (accumulated + nodeLen >= charIdx) {
        return { node, offset: charIdx - accumulated };
      }
      accumulated += nodeLen;
    }
    // Past end — clamp to end of last node
    if (textNodes.length) {
      const last = textNodes[textNodes.length - 1];
      return { node: last, offset: last.textContent?.length || 0 };
    }
    return null;
  }

  /** Lightweight fuzzy text finder — sliding window with character-match scoring.
   *  Much faster than Fuse.js + Levenshtein, and only used as a fallback. */
  private fuzzyFindInText(search: string, text: string): number {
    if (!search || !text || search.length > text.length) return -1;

    let bestIdx = -1;
    let bestScore = 0;
    const searchLen = search.length;

    for (let i = 0; i <= text.length - searchLen; i++) {
      const sub = text.substring(i, i + searchLen);
      let matches = 0;
      for (let j = 0; j < searchLen; j++) {
        if (sub[j] === search[j]) matches++;
      }
      const score = matches / searchLen;
      if (score > bestScore && score > 0.6) {
        bestScore = score;
        bestIdx = i;
      }
    }
    return bestIdx;
  }

  isBold(line: finalFeedData) {
    return line.formate == 'QES' || line.formate == 'QES-CONTINUE' || line.isBold;
  }

  startCondition(
    x: finalFeedData,
    firstCprdinate: feedAnnotCordinates,
    deep: boolean = true,
    lineIndex?: number
  ) {
    // Primary check: Time and UnicID
    let match = false;
    if (deep)
      match = this.util.timeToFram(x.time) >= this.util.timeToFram(firstCprdinate.t) && (!x.unicid || Number(x.unicid) >= Number(firstCprdinate.identity));
    else
      match = this.util.timeToFram(x.time) == this.util.timeToFram(firstCprdinate.t) && (!x.unicid || Number(x.unicid) == Number(firstCprdinate.identity));

    if (match) return true;

    // Fallback check: Page and Line (if available)
    // Note: this.pageno is the page of the current line 'x'
    if (firstCprdinate.p && firstCprdinate.l && lineIndex) {
      if (deep) {
        // Since we are iterating lines of 'this.pageno', we only care if this position is >= start coordinate
        // If coordinate page < current page, it's already started (true).
        // If coordinate page == current page, check line.
        // If coordinate page > current page, definitely false (Wait, startCondition means "are we PAST the start point?")
        // Yes, "Start Condition" = "Is current position >= Start Position"

        if (this.pageno > firstCprdinate.p) return true;
        if (this.pageno == firstCprdinate.p && lineIndex >= firstCprdinate.l) return true;
        return false;
      } else {
        // Exact match
        return this.pageno == firstCprdinate.p && lineIndex == firstCprdinate.l;
      }
    }

    return false;
  }

  endCondition(
    x: finalFeedData,
    endCordinate: feedAnnotCordinates,
    deep: boolean = true,
    lineIndex?: number
  ) {
    // Primary check: Time and UnicID
    let match = false;
    if (deep)
      match = this.util.timeToFram(endCordinate.t) >= this.util.timeToFram(x.time) && (!x.unicid || Number(endCordinate.identity) >= Number(x.unicid));
    else
      match = this.util.timeToFram(endCordinate.t) == this.util.timeToFram(x.time) && (!x.unicid || Number(endCordinate.identity) == Number(x.unicid));

    if (match) return true;

    // Fallback check: Page and Line
    // "End Condition" = "Is End Position >= Current Position"
    if (endCordinate.p && endCordinate.l && lineIndex) {
      if (deep) {
        if (endCordinate.p > this.pageno) return true;
        if (endCordinate.p == this.pageno && endCordinate.l >= lineIndex) return true;
        return false;
      } else {
        return endCordinate.p == this.pageno && endCordinate.l == lineIndex;
      }
    }
    return false;
  }

  loadAnnot(detail: feedAnnotations) {
    const firstCprdinate: feedAnnotCordinates = detail.jCordinates[0];
    const endCordinate: feedAnnotCordinates = detail.jCordinates[detail.jCordinates.length - 1];
    const mark = [];
    let isRefense: boolean = false;

    for (let [index, x] of this.lines.entries()) {
      if (this.startCondition(x, firstCprdinate, true, index + 1) && this.endCondition(x, endCordinate, true, index + 1)) {
        let annotText = x.lines.join('');

        if (this.startCondition(x, firstCprdinate, false, index + 1)) {
          annotText = firstCprdinate.text;
        }
        if (this.endCondition(x, endCordinate, false, index + 1)) {
          annotText = endCordinate.text;
        }

        // Placeholder coordinates — measureCoordsFromDOM() will replace
        // these with pixel-perfect values measured from the rendered DOM.
        const yTop = index * this.y_height + this.y_offset + this.margin;
        mark.push({
          text: annotText,
          l: index + 1,
          type: detail.cType,
          x: 0, y: yTop, width: 0, height: 23,
          x2: 0, y2: yTop
        });
      }
    }

    if (mark.length) {
      if (mark.length > 0) {
        const firstMark = mark[0];
        if (mark.length != detail.jCordinates?.length && firstMark.t != firstCprdinate.t && mark[0]['l'] == 1) {
          isRefense = true;
        }
      }

      const rectObj = { ...detail, jCordinates: mark, color: this.appendColor(detail.color) };
      const iconObj = this.iconPosition(rectObj);
      this.qFacts.push({ ...rectObj, ...iconObj, isRefense });
    }
  }

  appendColor(color: string) {
    let clr = (color || '#7DBAFF');
    return `${!clr.includes('#') ? '#' : ''}${clr}`;

  }


  iconClickEvent(annotation: feedAnnotations) {
    this.fds.emit('ANNOT-DETAILS', { id: annotation.id, cType: annotation.cType, source: 'ICON' })
  }

  onIconLoaded(annotation: feedAnnotations) {
    setTimeout(() => {
      this.fds.emit('ANNOT-RENDERED', { id: annotation.id })
    }, 200);

  }
}