import { Component, Input, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { HttpClient } from '@angular/common/http';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { KeyValue, KeyValuePipe } from '@angular/common';
import { WordIndex } from '../../../../interfaces/feed-index';
import { FeedIndexService } from '../../../../services/index/feed-index/feed-index.service';
import { SearchService } from '../../../../search/search.service';

interface PageLine {
  potition: string[];
  text?: string;
}

interface Page {
  title: string;
  lines: PageLine[];
  collapsed?: boolean;
}

import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'wordindex',
  standalone: true,
  imports: [FormsModule, ScrollingModule, KeyValuePipe, TranslateModule],
  templateUrl: './wordindex.component.html',
  styleUrl: './wordindex.component.scss'
})
export class WordindexComponent implements OnInit {

  pages: Page[] = [];
  searchTerm: string = '';
  // filteredPages: Page[] = this.pages;
  isLoading = false;

  // Virtual scroll properties
  // itemSize = 120; // Height of each item in pixels
  // minBufferPx = 200; // Minimum buffer size
  // maxBufferPx = 400; // Maximum buffer size
  // viewportHeight = 400; // Default viewport height
  @Input() wordWidth: number = 158;
  // @Input() filepath: string = '';
  // @ViewChild(CdkVirtualScrollViewport) viewport!: CdkVirtualScrollViewport;

  isNumericKey = (k: string) => /^\d+$/.test(k);  // only digits count as number


  sortStrFirstNumAfter = (a: KeyValue<string, unknown>, b: KeyValue<string, unknown>) => {
    const aNum = this.isNumericKey(a.key);
    const bNum = this.isNumericKey(b.key);

    if (aNum && !bNum) return 1;    // put strings before numbers
    if (!aNum && bNum) return -1;

    // both strings → lexicographic
    if (!aNum && !bNum) return a.key.localeCompare(b.key);

    // both numbers → numeric
    return Number(a.key) - Number(b.key);
  };

  wordIndexs: WordIndex = {};

  // index: WordIndex = {
  //   A: {
  //     absolute: { '1:15': null, '25:45': null },
  //     arrange: { '2:5': null, '2:6': null },
  //   },
  //   B: {
  //     branking: { '2:5': null, '2:6': null, '2:9': null }
  //   },
  // };
  constructor(private readonly http: HttpClient, private readonly fds: FeedDisplayService, private readonly feedIndex: FeedIndexService, private readonly searchService: SearchService) { }

  ngOnInit(): void {
    this.initList();
  }

  async initList() {
    if (this.isLoading) return;
    this.isLoading = true;
    this.wordIndexs = await this.feedIndex.getIndexData(this.searchTerm || null);
    this.isLoading = false;
  }

  onSearchInput() {
    if (!this.searchTerm || this.searchTerm.trim() === '') {
      this.initList();
    }
  }

  scrollToLine(position: string, word?: string) {
    const [page, line] = position.split(':');
    const pageNo = Number.parseInt(page) - 1;

    // Highlight the word in the feed using index-specific search (does not affect search bar)
    if (word) {
      const data = this.fds.getActiveFeedData();
      this.searchService.indexSearch(word, data, true, false);

      // Navigate to the match on the clicked page/line
      const matchIndex = this.searchService.matches.findIndex(
        m => m.page === pageNo && m.line === (Number.parseInt(line) - 1)
      );
      if (matchIndex > -1) {
        this.searchService.toMatch(matchIndex);
      }
    }

    // Activate mini split view if session is live (same as scroll-up behavior)
    if ((this.fds.sessionDetail?.cStatus === 'R' || this.fds.demoStream) && !this.fds.pausedState) {
      this.fds.pauseEvent();
    }

    this.fds.emit('SCROLL-TO-LINE', { page: pageNo, line: Number.parseInt(line), flag: 'W' })
  }
}
