import { Component, EventEmitter, Input, SimpleChanges } from '@angular/core';
import { FeedLineComponent } from '../../feed-line/feed-line.component';
import { activeFeedData, finalFeedData } from '../../../../../interfaces/feed-display.interface';
import { qMarksAnnots } from '../../../../../interfaces/annotation.interface';
import { FeedDisplayService } from '../../../../../services/feed-display/feed-display.service';
import { FeedUtilityService } from '../../../../../services/feed-utility/feed-utility.service';
import { realtimeEventParams } from '../../../../../interfaces/realtime.interface';

@Component({
  selector: 'text-layer',
  standalone: true,
  imports: [FeedLineComponent],
  templateUrl: './text-layer.component.html',
  styleUrl: './text-layer.component.scss'
})
export class TextLayerComponent {

  @Input() lines: finalFeedData[];
  @Input() showTimestamp: boolean;
  @Input() pageno: number;

  @Input() nCaseid: string;
  @Input() nUserid: string;

  @Input() qMarks: qMarksAnnots[] = [];

  @Input() smallFeed: boolean;

  @Input() activePageData: activeFeedData[];  
  @Input() realtimeEvent: EventEmitter<realtimeEventParams> = new EventEmitter<realtimeEventParams>();
  
  constructor(private readonly fds: FeedDisplayService, private feedUtility: FeedUtilityService) {

  }

  ngOnInit(): void {
   this.renderPageQMarks();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes["qMarks"] && !changes["qMarks"].firstChange) {
      this.renderPageQMarks();
    }
    if (changes["lines"] && !changes["lines"].firstChange) {
      this.renderPageQMarks();
    }

  }

  renderPageQMarks() {
    for (let [index, x] of this.lines.entries()) {
      x.nHid = this.checkForHighlight(this.pageno, index + 1, x.time, x.unicid);
    }
  }

  checkForHighlight(pageno: number, lineIndex: number, time: string, unicid: string): string | null {
    try {
      if (this.qMarks?.length) {
        // if (pageno == 7 && lineIndex == 11)
        //   debugger;
        const { cProtocol, isTrans } = this.fds.sessionDetail;
        let findObj;
        if (cProtocol == 'C') {
          findObj = this.qMarks.find(a => a.cPageno == pageno && a.cLineno == lineIndex);
        } else {
          findObj = this.qMarks.find(a => this.feedUtility.timeToFram(a.cTime) == this.feedUtility.timeToFram(time) && (!unicid || unicid == a.identity));
        }
        if (findObj) {
          return findObj.nHid;
        } 
        
        // Fallback: Check by Page/Line if not found (handles cases where time/unicid might differ, e.g. Demo mode)
        findObj = this.qMarks.find(a => a.cPageno == pageno && a.cLineno == lineIndex);
        if (findObj) {
          return findObj.nHid;
        } else {
          return null;
        }
      }

    } catch (error) {
      console.error(error);
    }
    return null
  }

  trackByLine(index: number, line: finalFeedData): string {
    return `${line.time}_${line.unicid}_${index}`;
  }

}
