import { Component, EventEmitter, Input, OnInit, SimpleChanges } from '@angular/core';
import { feeds } from '../../../../interfaces/feed.interface';
import { TextLayerComponent } from '../layers/text-layer/text-layer.component';
import { feedAnnotations, qMarksAnnots } from '../../../../interfaces/annotation.interface';
import { AnnotationLayerComponent } from '../layers/annotation-layer/annotation-layer.component';
import { CallOnVisibleDirective } from '../../../../directives/visible.directive';
import { ListRange } from '@angular/cdk/collections';
import { activeFeedData } from '../../../../interfaces/feed-display.interface';
import { realtimeEventParams } from '../../../../interfaces/realtime.interface';

import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'feed-page',
  standalone: true,
  imports: [TextLayerComponent, AnnotationLayerComponent, CallOnVisibleDirective, TranslateModule],
  templateUrl: './feed-page.component.html',
  styleUrl: './feed-page.component.scss',
  host: { 'style': 'display: block;' }
})
export class FeedPageComponent implements OnInit {
  @Input() itemSize: string;
  @Input() page: feeds;
  @Input() showTimestamp: boolean;

  ngOnInit() {
    console.log('FEED_PAGE: Initialized for page', this.page?.page);
  }
  @Input() annotations: feedAnnotations[] = []
  @Input() activeRange: ListRange;
  @Input() pageIndex: number;

  @Input() nCaseid: string;
  @Input() nUserid: string;

  @Input() visibleMarkNavModel: boolean;

  @Input() qMarks: qMarksAnnots[] = [];

  @Input() smallFeed: boolean;

  @Input() activePageData: activeFeedData[];

  @Input() realtimeEvent: EventEmitter<realtimeEventParams> = new EventEmitter<realtimeEventParams>();
  
  @Input() filterAnnots: string[] = [];
}
