  private startWidth: number = 0;


  @Input() ispdfactive: boolean;

  @Input() tabBox: tabmodel | null = null;

  // linkLines: linkLines[] = []

  /** Scroll-state values pushed to the custom scrollbar component. */
  smScrollTop: number = 0;
  smScrollHeight: number = 1;
  smClientHeight: number = 1;

  /** Called by the custom scrollbar when the user drags/clicks. */
  onScrollbarChange(scrollTop: number): void {
    if (this.viewport) {
      this.viewport.scrollToOffset(scrollTop);
    }
  }

  /** Sync scroll-state inputs from the cdk viewport to the custom scrollbar. */
  private syncScrollbar(): void {
    if (!this.viewport) return;
    const el = this.viewport.elementRef.nativeElement as HTMLElement;
    this.smScrollTop = el.scrollTop;
    this.smScrollHeight = el.scrollHeight;
    this.smClientHeight = el.clientHeight;
  }

  @HostListener('window:resize', ['$event'])
  onResize(event: Event) {
    this.adjustZoomForSplitView();
    this.updatePanelsSizes();
  }

  @HostListener('document:mousemove', ['$event'])
  onMouseMove(event: MouseEvent) {
    if (this.isResizing) {
      const deltaX = event.clientX - this.startX;
      const newWidth = this.startWidth + deltaX;

      // Constrain width between min and max values
      this.wordIndexWidth = Math.max(158, Math.min(200, newWidth));
    }
  }

  @HostListener('document:mouseup', ['$event'])
  onMouseUp(event: MouseEvent) {
    if (this.isResizing) {
      this.isResizing = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    }
  }

