  /*
    INITILIZATION
  */
  async initializeSession() {
    try {
      this.clearFeed();
      if (!this.nSesid) throw 'Session not selected';
          
      // Use Input Data if provided AND matches the current session ID
      if(this.sessionDetailData && this.sessionDetailData.nSesid === this.nSesid) {
          console.log('INIT_SESSION: Using sessionDetailData input');
          this.sessionDetail = this.sessionDetailData;
      } else {
         // Fetch session details from service (original behavior) or if input data is stale
         console.log('INIT_SESSION: Fetching new session details...');
         this.sessionDetail = await this.realtimeService.getSessionDetail(this.nSesid, this.nUserid);
      }

      // Bail out if the session detail couldn't be resolved. getSessionDetail
      // swallows HTTP errors and returns null on transient failures (network
      // blip, stale token, server returned empty body, transcript not yet
      // finalised). Without this guard the rest of the method dereferences
      // `this.sessionDetail.nSesid` / `.isTrans` / `.cStatus` on a null and
      // surfaces as the user-visible "ERROR in session: Cannot read properties
      // of null" toast. Warn-and-return keeps the preview pane empty instead.
      if (!this.sessionDetail) {
        console.warn('[initializeSession] No session detail for nSesid:', this.nSesid);
        return;
      }

      // The et_realtime_sessiondata SP returns stale isTrans=false for
      // published sessions (cStatus === 'P'), which routes loadFeed() to
      // the raw-tuple parser (appendPreviousSessionData). Published feeds
      // come back as pre-parsed objects, so that parser fails silently and
      // the RT dashboard shows "No Feed data Found" for published days.
      //
      // Individual-doc fixes this in buildSessionDocTab() by overriding
      // `detail.isTrans = detail.cStatus === 'P'` before passing the
      // corrected detail to <feed-display> via [sessionDetailData]. The RT
      // dashboard passes sessionDetailData from realtime.facade.ts, which
      // does NOT apply that override — so we mirror it here, unconditionally
      // on whichever path supplied the detail, so both the sessionDetailData
      // input and the direct-fetch fallback route published sessions to
      // appendRealtimeTranscriptData().
      if (this.sessionDetail && this.isPublishedTranscript && !this.sessionDetail.isTrans) {
        this.sessionDetail = { ...this.sessionDetail, isTrans: true };
      }

      // Cover page only applies to published transcripts viewed in
      // individual-doc / preview (isTranscViewer=true). RT module and drafts
      // don't render a cover. sessionDetail from realtime_sessiondata doesn't
      // expose cTransid, so resolve it via the transcript list (same endpoint
      // /transcript/transcript uses) and then fetch the TranscriptBuilder row
      // with getTranscriptDetail(cTransid) — the path that already works.
      this.coverData = null;
      this.coverDataSubject.next(null);
      if (this.isTranscViewer && this.isPublishedTranscript && this.sessionDetail?.nSesid) {
        try {
          const list: any[] = await this.transcriptService.getTranscriptList();
          const row = Array.isArray(list)
            ? list.find(t => t?.nSesid === this.sessionDetail.nSesid)
            : null;
          if (row?.cTransid) {
            const detail = await this.transcriptService.getTranscriptDetail(row.cTransid);
            const normalized = (detail && (Array.isArray(detail) ? detail[0] : detail)) || null;
            this.coverData = this.hasAnyCoverField(normalized) ? normalized : null;
            this.coverDataSubject.next(this.coverData);
            // Cover occupies virtual index 0 and isn't a numbered page, so
            // start the toolbar with the page field blank. As soon as the
            // user scrolls into the first transcript page, onPageChangeMostVisible
            // fills it with 1.
            if (this.coverData) {
              this._currentPage = 0;
            }
          }
        } catch (e) {
          console.warn('[cover-page] fetch failed:', e);
          this.coverData = null;
          this.coverDataSubject.next(null);
        }
      }

      // this.sessionDetail.isTrans = true;
      this.fds.sessionDetailUpdate(this.sessionDetail);
      // Fire-and-forget but trigger CD when it resolves: this component is OnPush and the
      // [annotations]="annot.annotations" binding to children won't pick up the new array
      // reference unless we explicitly markForCheck once fetchAnnotations completes. Without
      // this, REFRESH-SESSION-V2 leaves the inline feed showing stale annotations (e.g. DocLinks
      // disappear) while the marknav side fetches independently and updates correctly.
      this.annot.fetchAnnotations(this.nSesid, this.nUserid, this.sessionDetail.isTrans)
        .then(() => this.cdr.markForCheck())
        .catch(() => this.cdr.markForCheck());
      if (!this.fds.isLocal)
        this.fds.createBlankPages(this.sessionDetail?.maxNumber);
      this.isSessionLive = this.sessionLive();
    // Only load historical feed if we are NOT in a demo-only context or if we have reason to believe data exists.
    // For now, if we are about to start a demo (which we don't know yet) we can't skip.
    // But if connection is refused, this fails. 
    // Let's wrap it in try-catch to avoid breaking the rest of init.
    try {
        this.fds.loadFeed(this.nUserid, this.isSessionLive);
    } catch(e) {
        console.warn('Initial feed load failed (likely demo session or offline):', e);
    }

      this.setupRoom()


    } catch (error: unknown) {
      const msg = ErrorHandlerUtil.getErrorMessage(error);
      this.tost.error(msg && msg !== 'Unknown error' ? `ERROR in session: ${msg}` : 'ERROR in session');
    }
  }


  sessionLive(): boolean {
    const caseHasLiveSession = !!this.facade.currentCase()?.nSesid;
    return caseHasLiveSession && (this.sessionDetail.cStatus == 'R') && (!this.splitScreenEnabled || (this.splitScreenEnabled && this.primary)) && !this.compareEnabled;
  }

