  scrollToLast() {
    const total = this.fds.totalPages();
    if (total <= 0) return;

    if (!this.viewport) {
       // Viewport not ready (e.g. strict Initial load). Retry once.
       setTimeout(() => {
          if (this.viewport) this.scrollToLast();
       }, 200);
       return;
    }

    // "Ready" when either: (a) the viewport has rendered something,
    // or (b) Angular is stable (covers the case where nothing new renders).
    const ready$ = merge(
      this.viewport.renderedRangeStream.pipe(filter(r => r.end > 0)),
      this.ngZone.onStable.pipe(take(1)) // always emits on the next stable tick
    ).pipe(take(1));

    ready$
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(() => {
        this.viewport.checkViewportSize();
        // let layout settle before scrolling
        requestAnimationFrame(() => {
          this.scrollStrategy.forceRemeasure();

          // Chat-style scroll: only scroll enough to make the last line visible.
          // Calculate where the actual content ends (not the full 684px page box).
          const feedData = this.fds.feedDataSubject.getValue();
          const lastPage = feedData[feedData.length - 1];
          const lineCount = lastPage?.data?.length || 0;
          // 60px = page header (36px input + 24px mb-6), 24px per line
          const lastPageContentHeight = 60 + (lineCount * 24);
          const lastPageOffset = this.scrollStrategy.getOffsetForIndex(total - 1);
          const contentBottom = lastPageOffset + lastPageContentHeight;

          const viewportSize = this.viewport.getViewportSize();
          const currentScroll = this.viewport.measureScrollOffset();
          const currentBottom = currentScroll + viewportSize;

          if (contentBottom > currentBottom) {
            // Content extends below viewport — scroll just enough to show the last line
            this.viewport.scrollToOffset(contentBottom - viewportSize, 'auto');
          }
          // else: all content is already visible, don't scroll
        });
      });
  }


