  onWheel(event: WheelEvent) {
    // Enable split-screen on scroll-up during: live session OR demo mode
    // Only trigger if not already paused to prevent jerkiness
    if ((this.isSessionLive || this.fds.demoStream) && !this.fds.pausedState) {
      const viewport = this.viewport.measureScrollOffset();
      // Lower threshold (50px) to handle early pages with fewer lines
      // For page 1, don't trigger pause (nothing to scroll back to)
      const totalPages = this.fds.totalPages();
      if (event.deltaY < 0 && viewport > 50 && totalPages > 1) {
        this.fds.pauseEvent();
      }
    }
    // Resume feed when scrolling down to the bottom while paused
    else if ((this.isSessionLive || this.fds.demoStream) && this.fds.pausedState && event.deltaY > 0) {
      const bottomOffset = this.viewport.measureScrollOffset('bottom');
      if (bottomOffset <= 50) {
        this.fds.resumePause();
        this.activeFeedEnabled = false;
        this.activePageData = [];
        this.cdr.markForCheck();
      }
    }
  }

