import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges, inject } from '@angular/core';
import { MatSelectModule } from '@angular/material/select';
import { SessionListItem } from '../../../../interfaces/toolbar.interface';
import { ToolbarService } from '../../../../services/toolbar/toolbar.service';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { realtimeEventParams } from '../../../../interfaces/realtime.interface';
import { Router } from '@angular/router';
import { HeaderService } from '../../../../../core/services/header/header.service';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'compare-header',
  standalone: true,
  imports: [MatSelectModule, FormsModule, IconComponent, TranslateModule],
  templateUrl: './compare-header.component.html',
  styleUrl: './compare-header.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CompareHeaderComponent {
  private cdr = inject(ChangeDetectorRef);

  transcriptList: SessionListItem[] = [];


  @Input() nUserid: string;
  @Input() nCaseid: string;
  @Input() nSesid: string;
  @Output() nSesidChange: EventEmitter<string> = new EventEmitter<string>();

  @Input() splitScreenEnabled: boolean;
  @Input() primary: boolean;
  @Input() nSesStatus: string;
  selectedSesid: string;
  selectedSesStatus: string;

  @Input() realtimeEvent: EventEmitter<realtimeEventParams>;
  constructor(private toolbarService: ToolbarService, private router: Router, private hs: HeaderService) { }

  async ngOnInit() {
    this.selectedSesid = this.nSesid;
    this.getSessionList();
  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes['nSesStatus'] && changes['nSesStatus'].currentValue) {
      this.selectedSesStatus = changes['nSesStatus'].currentValue;
    }
  }

  OnSelect() {
    this.nSesid = this.selectedSesid;
    this.nSesidChange.emit(this.nSesid);
    this.selectedSesStatus = this.transcriptList.find(x => x.nSesid == this.selectedSesid)?.cStatus;
  }

  async getSessionList() {
    this.transcriptList = await this.toolbarService.getSessionList(this.nCaseid, this.nUserid, !this.splitScreenEnabled ? 'true' : null);

    // In split screen review mode, only show the current session
    if (this.splitScreenEnabled && !this.primary) {
      this.transcriptList = this.transcriptList.filter(x => x.nSesid === this.nSesid);
    }

    this.cdr.markForCheck();
  }

  closeSplitScreen() {

    this.realtimeEvent.emit({ type: 'SWITCH-MODE-DISABLE' })
  }


  redirectToScript() {
    const nCaseid = this.hs.Casedetail?.nCaseid || this.hs.nCaseid;
    const url = this.router.serializeUrl(
      this.router.createUrlTree(['/realtime/feed', btoa(JSON.stringify({ nSesid: this.nSesid || 0, nCaseid: this.hs.Casedetail?.nCaseid || this.hs.nCaseid }))])
    );
    window.open(url, '_blank');
  }
}
