import { feedAnnotations } from "../../../../interfaces/annotation.interface";
import { feedPage, finalFeedData } from "../../../../interfaces/feed-display.interface";
import { AnnotsService } from "../../../../services/annots/annots.service";
import { FeedDisplayService } from "../../../../services/feed-display/feed-display.service";


interface issueCordinates {
    t: string;
    l: number;
    p: number;
    text: string;
    oP: number;
    oL: number
    identity: string;
}


export class PerformAnnotComponent {

    // Copy-to-clipboard state — set by FeedDisplayComponent via toolBarEvents.
    // Checked at the top of onAnnotPerform: if true, the selected text is
    // copied (with optional metadata) and the annotation popup is suppressed,
    // matching PDF's docmouseup early-return pattern at pdf.component.ts:1545.
    copyToClipboard: boolean = false;
    copyDocName: boolean = false;
    copyPagination: boolean = false;

    private isSelection = true;
    private firstLineObj = {
        text: null,
        element: null,
        isFirstSelected: false,
        isTextGot: false,
        page: null,
        line: null
    }
    resetSelection = () => {
        this.firstLineObj = {
            text: null,
            element: null,
            isFirstSelected: false,
            isTextGot: false,
            page: null,
            line: null
        }
    }



    constructor(protected fds: FeedDisplayService, protected annot: AnnotsService) {

    }


    OnSelectionStart(e) {
        this.isSelection = true;
        this.resetSelection();
    }

    onAnnotPerform(event: MouseEvent) {
        if (this.getIsSmall()) return;

        // Copy-to-clipboard mode: intercept before annotation logic (mirrors
        // pdf.component.ts:1545-1550 early return in docmouseup).
        console.log('[annot] onAnnotPerform — copyToClipboard:', this.copyToClipboard, 'copyDocName:', this.copyDocName);
        if (this.copyToClipboard) {
            console.log('[annot] COPY MODE ACTIVE — intercepting, suppressing annotation popup');
            this.performCopyToClipboard(event);
            return;
        }

        this.isSelection = false;
        const sel = window.getSelection();
        if (!sel || sel.isCollapsed) return;
        const findLineElem = (node) => {
            if (!node) return null;
            return node.nodeType === 3
                ? node.parentElement.closest('.line')
                : node.closest('.line');
        };
        const endLineObj = {
            text: null,
            element: null,
            isFirstSelected: false,
            isTextGot: false,
            page: null,
            line: null
        }
        const string = sel.toString().trim();
        endLineObj.text = string.split('\n')[string.split('\n').length - 1];
        endLineObj.isTextGot = true;
        endLineObj.element = findLineElem(sel.focusNode);
        if (endLineObj.element) {
            endLineObj.page = endLineObj.element?.getAttribute("pno")
            endLineObj.line = endLineObj.element?.getAttribute("lno")
            endLineObj.isFirstSelected = true;
        }

        if (!endLineObj.page) { return; }
        if (!this.firstLineObj?.page) {
            this.firstLineObj = { ...endLineObj }
        };
        const startCount = this.firstLineObj.page * 25 + (Number(this.firstLineObj.line) - 1);
        const endCount = endLineObj.page * 25 + (Number(endLineObj.line) - 1);
        if (startCount == -1 || endCount == -1) { return; }

        let startObj, endObj;
        if (endCount > startCount) {
            startObj = this.firstLineObj;                     // {page, line, …}
            endObj = endLineObj;
        } else {
            startObj = endLineObj;                     // {page, line, …}
            endObj = this.firstLineObj;
        }

        const feedData = this.fds.getActiveFeedData();
        // const feedValue = feedData.filter(x => x.page >= startObj.page && x.page <= endObj.page);

        // ── BOUNDARY FIX ──────────────────────────────────────────────────
        // When the browser places the Range boundary at offset 0 of the next
        // line's first text node (end overshoot) or at the end of the previous
        // line's last text node (start overshoot), the detected line number is
        // off by one.  Correct both ends using page/line arithmetic so that
        // annotations are saved with accurate coordinates.
        try {
            const range = sel.getRangeAt(0);

            // End overshoot: range ends at offset 0 of the next line's start
            // → no text from that line is selected → step endObj back one line.
            if (range.endOffset === 0) {
                const eLine = findLineElem(range.endContainer);
                if (eLine) {
                    const pre = eLine.querySelector('pre');
                    let atLineStart = false;
                    if (range.endContainer.nodeType === 3 && pre) {
                        const tw = document.createTreeWalker(pre, NodeFilter.SHOW_TEXT);
                        atLineStart = tw.nextNode() === range.endContainer;
                    } else if (range.endContainer === pre || range.endContainer === eLine) {
                        atLineStart = true;
                    }
                    if (atLineStart) {
                        let p = +endObj.page, l = +endObj.line;
                        l -= 1;
                        if (l < 1) { l = 25; p -= 1; }
                        if (p >= 1) {
                            endObj.page = String(p); endObj.line = String(l);
                        }
                    }
                }
            }

            // Start overshoot: range starts at the end of the prev line's last
            // text node → first selected content is on the next line → step
            // startObj forward one line.
            if (range.startContainer.nodeType === 3 &&
                range.startOffset === range.startContainer.textContent.length) {
                const sLine = findLineElem(range.startContainer);
                if (sLine) {
                    const pre = sLine.querySelector('pre');
                    if (pre) {
                        const tw = document.createTreeWalker(pre, NodeFilter.SHOW_TEXT);
                        let last: Node = null;
                        while (tw.nextNode()) last = tw.currentNode;
                        if (last === range.startContainer) {
                            let p = +startObj.page, l = +startObj.line;
                            l += 1;
                            if (l > 25) { l = 1; p += 1; }
                            startObj.page = String(p); startObj.line = String(l);
                        }
                    }
                }
            }
        } catch (_) { /* boundary detection failed */ }

        const selectedCordinates = this.getSelectedAsciiStrings(
            feedData,
            { page: +startObj.page, line: startObj.line },
            { page: +endObj.page, line: endObj.line }
        );

        if (selectedCordinates.length) {
            if (endCount > startCount) {
                selectedCordinates[0].text = startObj.text;
                selectedCordinates[selectedCordinates.length - 1].text = endObj.text;
            } else {
                selectedCordinates[0].text = endObj.text;
                selectedCordinates[selectedCordinates.length - 1].text = startObj.text;
            }
            const selectedText = selectedCordinates.map(x => x.text || '').join('\n');

            const nPage = selectedCordinates[0]?.p || 0;
            const nLine = selectedCordinates[0]?.l || 0;

            const annot: feedAnnotations = {
                id: this.generateUniqueId(),
                jCordinates: selectedCordinates,
                isTemp: true,
                nPage,
                nLine,
                fullText: selectedText || ''
            }
            this.annot.removeTemp();
            this.annot.set(annot);
            this.annot.enableAnnotBox({ x: event.screenX, y: event.screenY, width: 0, height: 0 });

            /*const annotation: Annotation = {
                temp: true,
                nIDid: null,
                id: this.generateUniqueId(),
                pageIndex: startObj.page,
                text: selectedText,
                color: '5c9dff', // Set your desired color here
                cordinates: selectedCordinates
            };*/

            this.clearSelection();
            /*  const lastIsid = this.annotationService.getAnnotLastIssue();
              if (!lastIsid?.nIid) {
                  this.onAnnotEvent(annotation, feedValue[0], startObj.page);
              } else {
                  this.saveAnnotations(annotation);
              }*/

        }
        this.resetSelection();

    }

    private generateUniqueId(): string {
        return Math.random().toString(36).substr(2, 9);
    }

    getSelectedAsciiStrings(
        feedPages: feedPage[],
        start: { page: number; line: number },
        end: { page: number; line: number }
    ): issueCordinates[] {
        const result: issueCordinates[] = [];
        const total_lines = 25;

        // const feedData = feedPages.flatMap(a => a.data);
        const feedData = feedPages.flatMap(d => {
            const arr = d.data || [];
            const padCount = 25 - arr.length;
            // create an array of blank objects only if needed
            const padding = padCount > 0
                ? Array.from({ length: padCount }, () => ({ time: '00:00:00:00', asciiValue: [], lines: [''], oPage: 0, oLine: 0, unicid: '0' })) // Adjust the properties as needed
                : [];
            return [...arr, ...padding];
        })

        const startIndex = (start.page - 1) * 25 + (Number(start.line) - 1);
        const endIndex = (end.page - 1) * total_lines + (Number(end.line) - 1);

        for (let i = startIndex; i <= endIndex; i++) {
            const entry: finalFeedData = feedData[i] as finalFeedData;
            if (!entry) continue;
            const page = (Math.floor(i / total_lines) + 1);
            const str = entry.lines.join('').trimEnd();

            const lineNo = (i % total_lines) + 1; // Calculate line number based on index
            if (str) {
                result.push({
                    text: str,
                    t: entry.time,
                    l: lineNo,
                    p: page,
                    oP: entry.oPage,
                    oL: entry.oLine,
                    identity: entry.unicid || '0'
                });
            }
        }
        return result;
    }

    onMouseMoveSelection(e) {
        if (this.getIsSmall()) return;
        if (!this.isSelection) return;
        const sel = window.getSelection();
        if (!sel || sel.isCollapsed) return;
        const str = sel.toString();
        if (this.firstLineObj.isFirstSelected) {
            if (document.documentElement.contains(this.firstLineObj.element)) {
                if (!this.firstLineObj.isTextGot) {
                    this.firstLineObj.text = str.split('\n')[0];
                    console.log(this.firstLineObj.text)
                }

                if (str?.split('\n')?.length > 1)
                    this.firstLineObj.isTextGot = true;
                // else

                // console.warn('Mouse move selection:', this.firstLineObj.text);
            }
        }
        if (this.firstLineObj.isFirstSelected) return;
        const findLineElem = (node) => {
            if (!node) return null;
            return node.nodeType === 3
                ? node.parentElement.closest('.line')
                : node.closest('.line');
        };
        this.firstLineObj.element = findLineElem(sel.anchorNode);
        if (this.firstLineObj.element) {
            this.firstLineObj.page = this.firstLineObj.element?.getAttribute("pno")
            this.firstLineObj.line = this.firstLineObj.element?.getAttribute("lno")
            this.firstLineObj.isFirstSelected = true;
        }
    }

    protected getIsSmall(): boolean {
        return null; // Replace with actual implementation
    }

    /** Subclass hook for toast notification after successful copy. */
    protected onCopySuccess(): void {
        // Override in FeedDisplayComponent to call tost.success(...)
    }

    /** Subclass hook: returns session/doc name for copy metadata. */
    protected getSessionName(): string {
        return '';  // Override in FeedDisplayComponent
    }

    protected getUserId(): string {
        return null; // Replace with actual implementation
    }

    protected getCurrentSession(): any {
        return null
    }

    protected onAnnotEvent(annotation, page, pageIndex) {

    }


    clearSelection() {
        const sel = window.getSelection?.();
        if (sel) {
            // modern browsers
            sel.removeAllRanges();
        } else if ((document as any).selection) {
            // IE ≤ 11
            (document as any).selection.empty();
        }
    }

    /**
     * Copy selected feed text to clipboard with optional metadata.
     * Mirrors pdf.component.ts:CopySelection (lines 3157-3187).
     *
     * Uses the same DOM traversal as onAnnotPerform to find start/end lines,
     * then builds selectedCordinates to get per-line page.line + text. The
     * copied output includes line references so the paste in Word reads:
     *
     *   1.5   SP01: Just talking to anyone on the microphones.
     *   1.6   SP02: Testing, testing. Mic mic testing.
     *
     *   Day-02
     *   {1.5-1.6}
     */
    private performCopyToClipboard(event: MouseEvent) {
        const sel = window.getSelection();
        if (!sel || sel.isCollapsed || !sel.toString().trim()) return;

        // Find start + end line elements from selection anchors
        const findLineElem = (node) => {
            if (!node) return null;
            return node.nodeType === 3
                ? node.parentElement?.closest('.line')
                : node.closest('.line');
        };
        const startEl = findLineElem(sel.anchorNode);
        const endEl = findLineElem(sel.focusNode);
        if (!startEl) return;

        const startPage = +(startEl.getAttribute('pno') || 0);
        const startLine = +(startEl.getAttribute('lno') || 0);
        const endPage = +(endEl?.getAttribute('pno') || startPage);
        const endLine = +(endEl?.getAttribute('lno') || startLine);

        // Normalize start/end so start ≤ end
        let s = { page: startPage, line: startLine };
        let e = { page: endPage, line: endLine };
        const sIdx = s.page * 25 + s.line;
        const eIdx = e.page * 25 + e.line;
        if (eIdx < sIdx) [s, e] = [e, s];

        // Build per-line coordinates with text from feed data
        const feedData = this.fds.getActiveFeedData();
        const coords = this.getSelectedAsciiStrings(feedData, s, e);

        if (!coords.length) return;

        // Build text-only output (no line numbers in the body — user wants
        // clean text that reads naturally when pasted into Word).
        const lines = coords.map(c => c.text || '');
        let textToCopy = lines.join('\r\n');

        // Append optional metadata at the bottom:
        //   Day-01
        //   {Page No 1, Line No 5-10}
        let extra = '';
        const sessionName = this.getSessionName();
        if (this.copyDocName && sessionName) {
            extra += sessionName;
        }
        if (this.copyPagination && coords.length) {
            const firstCoord = coords[0];
            const lastCoord = coords[coords.length - 1];
            // Group by page — if selection spans multiple pages, show range per page
            if (firstCoord.p === lastCoord.p) {
                // Single page: {Page No 1, Line No 5-10}  or  {Page No 1, Line No 5}
                const lineRef = firstCoord.l === lastCoord.l
                    ? `${firstCoord.l}`
                    : `${firstCoord.l}-${lastCoord.l}`;
                extra += (extra ? '\r\n' : '') + `{Page No ${firstCoord.p}, Line No ${lineRef}}`;
            } else {
                // Multi-page: {Page No 1, Line No 20 - Page No 2, Line No 5}
                extra += (extra ? '\r\n' : '') + `{Page No ${firstCoord.p}, Line No ${firstCoord.l} - Page No ${lastCoord.p}, Line No ${lastCoord.l}}`;
            }
        }
        if (extra) {
            textToCopy += `\r\n\r\n${extra}`;
        }

        // Copy to clipboard + toast
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(textToCopy).then(() => {
                this.onCopySuccess();
            });
        }

        // Clear selection after copy (matches PDF behavior)
        this.clearSelection();
    }
}