import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { realtimeEventParams } from '../../../../interfaces/realtime.interface';
import { distinctUntilChanged, Observable, Subscription } from 'rxjs';
import { feeds } from '../../../../interfaces/feed.interface';
import { activeFeedData, finalFeedData } from '../../../../interfaces/feed-display.interface';
import { FeedLineComponent } from '../feed-line/feed-line.component';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';

import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'active-feed',
  standalone: true,
  imports: [IconComponent, MatTooltipModule, FeedLineComponent, TranslateModule],
  templateUrl: './active-feed.component.html',
  styleUrl: './active-feed.component.scss'
})
export class ActiveFeedComponent implements OnInit {
  @Input() splitScreenEnabled: boolean;
  @Input() realtimeEvent: EventEmitter<realtimeEventParams>;
  @Input() nSesid: string;
  @Input() feedData$: Observable<finalFeedData[]>
  @Input() showTimestamp: boolean;
  @Input() zoomLevel: number;


  @Input() activeFeedEnabled: boolean;
  @Output() activeFeedEnabledChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  activePage: number;
  @Input() activePageData: activeFeedData[];
  @Output() activePageDataChange: EventEmitter<activeFeedData[]> = new EventEmitter<activeFeedData[]>();
  lineNo: number;
  @Input() review: boolean;
  private feedDataSub: Subscription;
  constructor(private readonly fds: FeedDisplayService) {

  }
  ngOnInit(): void {
    this.lineNo = this.fds.sessionDetail?.nLines || 25
    this.feedDataSub = this.feedData$.pipe(distinctUntilChanged((a, b) => JSON.stringify(a) === JSON.stringify(b))).subscribe((values: finalFeedData[]) => {
      // const activeFeedSubject = this.fds.getActiveFeedSubject();
      // const values =  activeFeedSubject.getValue();
      this.activePage = null;
      this.activePageData = [];
      if (values?.length) {

        this.activePageData = values.map((item, i) => {
          this.activePage = Math.floor(item.lineIndex / this.lineNo) + 1;
          const lineIndex = item.lineIndex % this.lineNo;
          return {
            item,
            page: this.activePage,
            index: lineIndex                  // restart from 1 if less than 6 items
          };
        })

        // console.warn('FINAL',this.activePageData);

        /* const lastPage: feeds = structuredClone(values[values?.length - 1]);
         if (lastPage) {
           this.activePage = lastPage.page;
           this.activePageData = [...(lastPage.data || [])]
             .slice(-6)
             .map((item, i) => {
               const totalLength = (lastPage.data || []).length;
               return {
                 item,
                 index: totalLength >= 6
                   ? totalLength - 6 + i + 1   // keep original index (1-based)
                   : i + 1                     // restart from 1 if less than 6 items
               };
             });
           // const allPageData = this.fds.feedDataHoldSubject.getValue();
           // try {
           //   // ar
           //   const remainingPageData = (lastPage.data || []).slice(0, ((lastPage.data || []).length - 3) >= 0 ? ((lastPage.data || []).length - 3) : 1);
           //   const holdData: feeds[] = [...values]
           //   holdData[holdData?.length - 1].data = remainingPageData;
           //   this.fds.feedDataHoldSubject.next(holdData);
           // } catch (error) {
           //   console.error(error);
           // }
         }*/

      }
      this.activePageDataChange.emit(this.activePageData);
    });
  }


  closeActiveFeed() {
    this.activePageData = [];
    this.activePageDataChange.emit(this.activePageData);
    this.activeFeedEnabled = false;
    this.activeFeedEnabledChange.emit(this.activeFeedEnabled);
    this.fds.resumePause(); // Resume feed so pausedState resets and scroll-up can re-trigger
  }

  openSplitScreen() {
    this.realtimeEvent.emit({ type: 'SWITCH-MODE-ENABLED', data: { nSesid: this.nSesid } })
  }

  checkTrackBy(line: activeFeedData,i:number) {
    return `${line?.item?.time}_${line?.item?.unicid}_${i}`
  }
}