import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';

export interface TranscriptCover {
  cCasetype?: string;
  cCCaseno?: string;
  cClaiment?: string;
  cClaimentH?: string;
  cRespondent?: string;
  cRespondentH?: string;
  cArbitrator?: string;
  cCDay?: number | string;
  /** ISO-instant variant of the hearing date. Still received from the
   *  backend; no longer rendered on the cover page (day label is shown
   *  on its own and the date is captured elsewhere). */
  dCDate?: string;
  /** Pre-formatted hearing date (MM-DD-YYYY) returned by the backend
   *  alongside `dCDate`. Still received; no longer rendered on the cover. */
  dCDate1?: string;
  cBClaimentH?: string;
  cBClaiment?: string;
  cBRespondentH?: string;
  cBRespondent?: string;
  cTitle?: string;
}

@Component({
  selector: 'transcript-cover-page',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './transcript-cover-page.component.html',
  styleUrl: './transcript-cover-page.component.scss',
})
export class TranscriptCoverPageComponent {
  @Input() cover: TranscriptCover | null = null;

  splitLines(value: string | undefined | null): string[] {
    if (!value) return [];
    return value.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  }

  // The admin form already stores values like "Day 1" (its default is "Day 1"
  // and users typically type "Day N"), so a literal "Day " prefix in the
  // template would render "Day Day N". Use the stored value as-is when it
  // already begins with "Day "; otherwise prepend it (covers legacy numeric
  // values such as 1 or "2").
  dayLabel(): string {
    const v = this.cover?.cCDay;
    if (v == null || v === '') return '';
    const s = String(v).trim();
    return /^day\b/i.test(s) ? s : `Day ${s}`;
  }
}
