import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Inject, OnInit } from '@angular/core';
import { FormControl, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { NgSelectModule } from '@ng-select/ng-select';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IssueService } from '../../../../services/issue/issue.service';
import { ContactService } from '../../../../../shared/services/contact/contact.service';
import { CommonService } from '../../../../../shared/services/common/common.service';
import { TaskService } from '../../../../../shared/services/task/task.service';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { SecureStorageService } from '../../../../../core/services/storage/secure-storage.service';
import { UserDetail } from '../../../../../core/interfaces/login.interface';
import { environment } from '../../../../../../environments/environment';
import { FILTER_LIST, QFACT_DATE_TYPE } from '../../../../../shared/interfaces/mark-nav-filter.interface';
import { codeData } from '../../../../../shared/interfaces/common.interface';
import { DateFormComponent } from '../../../../../marking/components/fact/date-form/date-form.component';
import { DatepickerComponent } from '../../../../../shared/components/datepicker/datepicker.component';
import { TeamshareComponent } from '../../../../../marking/components/fact/teamshare/teamshare.component';

/** Per-filter-group state — data fields match markNavjFilters for direct backend reuse */
export interface FilterGroup {
  value: string;
  cCategory: string;
  /** Dropdown items (issues or claim categories) */
  items: any[];

  // ── ng-select reset helpers (UI only) ──────────────────
  resetSelect: any;
  resetIssueSelect: any;
  resetRelevanceSelect: any;
  resetImpactSelect: any;
  resetContactSelect: any;
  resetRoleSelect: any;
  resetPartySelect: any;
  resetCompanySelect: any;
  resetTaskSelect: any;
  resetAssigneeSelect: any;
  resetStatusSelect: any;
  resetPrioritySelect: any;
  resetFileTypeSelect: any;

  // ── Badge display helpers (UI only) ────────────────────
  claimBadges: any[];
  issueBadges: any[];
  relBadges: any[];
  impBadges: any[];
  fileTypeBadges: any[];
  contactBadges: any[];
  roleBadges: any[];
  partyBadges: any[];
  companyBadges: any[];
  taskBadges: any[];
  assigneeBadges: any[];
  statusBadges: any[];
  priorityBadges: any[];

  // ── markNavjFilters-compatible fields ──────────────────
  // Claim
  jClaims: string[];
  // Issue
  jIssues: string[];
  jRels: number[];
  jImps: number[];
  IsNote: boolean;
  IsFactlink: boolean;
  IsComment: boolean;
  // Fact
  jDate: any;
  jFiletypes: number[];
  selecteddatetype: number;
  createDate: { start: string; end: string } | null;
  cType: 'M' | 'S' | null;
  // Contact
  jContacts: string[];
  jCRoles: string[];
  jCPartys: number[];
  jCCompanies: string[];
  IsContactNote: boolean;
  // Task
  jTasks: string[];
  jTShared: string[];
  jTStatus: number[];
  jTPriority: number[];
  dTDate: string;
  IsTaskDesc: boolean;
}

@Component({
  selector: 'app-export-transcript',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    NgSelectModule,
    MatCheckboxModule,
    MatSelectModule,
    MatFormFieldModule,
    MatRadioModule,
    IconComponent,
    ButtonComponent,
    DateFormComponent,
    DatepickerComponent,
    TeamshareComponent,
  ],
  templateUrl: './export-transcript.component.html',
  styleUrl: './export-transcript.component.scss',
})
export class ExportTranscriptComponent implements OnInit {
  isAdvanced = false;
  isLoading = false;
  showFilterGroupDropdown = false;
  frm: FormGroup;

  current_session: any;
  nUserid: any;
  cIsDemo: string = 'N';
  nSesid: any;
  userdetail: UserDetail;

  /** Fixed filter group categories */
  allCategories = FILTER_LIST.map(f => ({ value: f.value, cCategory: f.name }));
  allClaimCategories: any[] = [];
  allIssues: any[] = [];
  allContacts: any[] = [];
  allFileTypes: codeData[] = [];
  allRoles: any[] = [];
  allParties: codeData[] = [];
  allCompanies: any[] = [];
  allTasks: any[] = [];
  allTeamUsers: any[] = [];
  allTaskStatuses: codeData[] = [];
  allTaskPriorities: codeData[] = [];
  allRelevance: codeData[] = [];
  allImpact: codeData[] = [];

  qfactdatetype = QFACT_DATE_TYPE;

  filterGroups: FilterGroup[] = [];

  /** Allowed filter group values per annotation type */
  /** Mirrors FILTER_LIST allowedTabs: CL/I allow QF+L, FD/C/T allow F+L only */
  private readonly typeGroupMap: Record<string, string[]> = {
    'ALL':   ['CL', 'I', 'FD', 'C', 'T'],
    'QMARK': [],
    'QFACT': ['CL', 'I'],
    'FACT':  ['CL', 'I', 'FD', 'C', 'T'],
    'LINK':  ['CL', 'I', 'FD', 'C', 'T'],
  };

  annotationTypes = [
    { value: 'ALL',   label: 'All' },
    { value: 'QMARK', label: 'Quick Mark' },
    { value: 'QFACT', label: 'Q Fact' },
    { value: 'FACT',  label: 'Fact' },
    { value: 'LINK',  label: 'Link' },
  ];

  annotationOptions = [
    { value: 'ALL',     label: 'All Annotations' },
    { value: 'NONE',    label: 'No Annotations' },
    { value: 'CREATOR', label: 'Creator' },
  ];

  layoutOptions = [
    { value: 'FULL_PAGE',  label: 'Full Page' },
    { value: 'CONDENSED',  label: 'Condensed' },
  ];

  pages = Array.from({ length: 999 }, (_, i) => i + 1);
  downloadPath = `${environment.cloudUrl2}${environment.realtimeserive}/realtime-transcripts/exports/`;

  constructor(
    private issueService: IssueService,
    private contactService: ContactService,
    private commonService: CommonService,
    private taskService: TaskService,
    private store: SecureStorageService,
    private cdr: ChangeDetectorRef,
    private tost: TostbarService,
    public dialogRef: MatDialogRef<ExportTranscriptComponent>,
    @Inject(MAT_DIALOG_DATA) private dialogData: { current_session: any; nUserid: any; cIsDemo?: string; nSesid?: any }
  ) {}

  async ngOnInit() {
    if (this.dialogData) {
      this.current_session = this.dialogData.current_session;
      this.nUserid = this.dialogData.nUserid;
      this.cIsDemo = this.dialogData.cIsDemo || 'N';
      this.nSesid = this.dialogData.nSesid || this.current_session?.nSesid;
    }

    const baseName = this.current_session?.cName || '';
    // OR-check both publish paths (cStatus='P' from RT publish OR
    // isTranscript+isUploaded from the upload-publish path) so the export
    // filename suffix correctly reads "Final" for any published session,
    // not just RT-published ones. Mirrors the canonical isTrans expression
    // used by et_realtime_sessiondata + every other publish-state check.
    const isPublished = this.current_session?.cStatus === 'P'
      || (this.current_session?.isTranscript && this.current_session?.isUploaded);
    const suffix = isPublished ? 'Final' : 'Draft';
    const defaultExportName = baseName ? `${baseName} - ${suffix}` : '';

    this.frm = new FormGroup({
      cExportName:        new FormControl(defaultExportName, [Validators.required]),
      bAnnotations:       new FormControl(false),
      bCover:             new FormControl(false),
      bWordIndex:         new FormControl(false),
      bTimestamp:         new FormControl(false),
      cPageRange:         new FormControl('A'),
      nPageFrom:          new FormControl({ value: null, disabled: true }),
      nPageTo:            new FormControl({ value: null, disabled: true }),
      cLayout:            new FormControl('FULL_PAGE'),
      cAnnotations:       new FormControl('ALL'),
      cAnnotationType:    new FormControl('ALL'),
      bAnnotationSummary: new FormControl(true),
    });

    this.frm.get('cAnnotationType').valueChanges.subscribe((type: string) => {
      const allowed = this.typeGroupMap[type] ?? ['CL', 'I', 'FD', 'C', 'T'];
      this.filterGroups = this.filterGroups.filter((g) => allowed.includes(g.value));
      this.cdr.detectChanges();
    });

    // Handle page range selection changes
    this.frm.get('cPageRange').valueChanges.subscribe((value: string) => {
      const nPageFromCtrl = this.frm.get('nPageFrom');
      const nPageToCtrl = this.frm.get('nPageTo');

      if (value === 'A') {
        // Disable when "All" is selected
        nPageFromCtrl.reset(null, { emitEvent: false });
        nPageToCtrl.reset(null, { emitEvent: false });
        nPageFromCtrl.disable({ emitEvent: false });
        nPageToCtrl.disable({ emitEvent: false });
      } else {
        // Enable when "Range" is selected
        nPageFromCtrl.enable({ emitEvent: false });
        nPageToCtrl.enable({ emitEvent: false });
      }
      this.cdr.detectChanges();
    });

    this.userdetail = await this.store.getUserInfo();

    if (this.current_session) {
      await this.fetchData();
    }
  }

  async fetchData() {
    try {
      const nCaseid = this.current_session.nCaseid;
      const [claimCategories, [, issues], contacts, fileTypes, roles, parties, companies, taskRes, teamUsers, taskStatuses, taskPriorities, relevance, impact] = await Promise.all([
        this.issueService.getCategory(nCaseid, this.nUserid),
        this.issueService.fetchIssueListV2({ nCaseid, nSessionid: this.current_session.nSesid, nUserid: this.nUserid, nIDid: null }),
        this.contactService.getContactList(nCaseid),
        this.commonService.getCode(23),
        this.contactService.getContactCaserolelist(nCaseid),
        this.commonService.getCode(22),
        this.contactService.getContactCompany(nCaseid),
        this.taskService.getTaskList(nCaseid, 'FT'),
        this.commonService.getMyTeamUsers(nCaseid),
        this.commonService.getCode(25),
        this.commonService.getCode(17),
        this.commonService.getCode(4),
        this.commonService.getCode(5),
      ]);
      this.allClaimCategories = (claimCategories || []).map((c: any) => ({ nIid: c.nICid, cIName: c.cCategory }));
      this.allIssues          = issues || [];
      this.allContacts        = contacts || [];
      this.allFileTypes       = fileTypes || [];
      this.allRoles           = roles || [];
      this.allParties         = parties || [];
      this.allCompanies       = companies || [];
      this.allTasks           = (taskRes as any)?.[0] || [];
      this.allTeamUsers       = (teamUsers || []).filter((u: any) => u.nUserid !== this.nUserid);
      this.allTaskStatuses    = taskStatuses || [];
      this.allTaskPriorities  = taskPriorities || [];
      this.allRelevance       = relevance || [];
      this.allImpact          = impact || [];
      this.cdr.detectChanges();
    } catch (e) {
      console.error(e);
    }
  }

  get availableCategories(): any[] {
    const allowed = this.typeGroupMap[this.frm?.value?.cAnnotationType] ?? ['CL', 'I', 'FD', 'C', 'T'];
    const added = new Set(this.filterGroups.map((g) => g.value));
    return this.allCategories.filter((c) => allowed.includes(c.value) && !added.has(c.value));
  }

  addFilterGroup(cat: any) {
    const items =
      cat.value === 'CL' ? this.allClaimCategories :
      cat.value === 'I'  ? this.allIssues : [];
    this.filterGroups.push({
      value: cat.value,
      cCategory: cat.cCategory,
      items,
      resetSelect: null, resetIssueSelect: null, resetRelevanceSelect: null,
      resetImpactSelect: null, resetContactSelect: null, resetRoleSelect: null,
      resetPartySelect: null, resetCompanySelect: null, resetTaskSelect: null,
      resetAssigneeSelect: null, resetStatusSelect: null, resetPrioritySelect: null,
      resetFileTypeSelect: null,
      claimBadges: [], issueBadges: [], relBadges: [], impBadges: [],
      fileTypeBadges: [], contactBadges: [], roleBadges: [], partyBadges: [],
      companyBadges: [], taskBadges: [], assigneeBadges: [], statusBadges: [],
      priorityBadges: [],
      jClaims: [], jIssues: [], jRels: [], jImps: [],
      IsNote: false, IsFactlink: false, IsComment: false,
      jDate: null, jFiletypes: [], selecteddatetype: 1, createDate: null,
      cType: 'S',
      jContacts: [], jCRoles: [], jCPartys: [], jCCompanies: [], IsContactNote: false,
      jTasks: [], jTShared: [], jTStatus: [], jTPriority: [], dTDate: '', IsTaskDesc: false,
    });
    this.showFilterGroupDropdown = false;
    this.cdr.detectChanges();
  }

  removeFilterGroup(index: number) {
    this.filterGroups.splice(index, 1);
    this.cdr.detectChanges();
  }

  clearAllFilters() {
    this.filterGroups = [];
    this.cdr.detectChanges();
  }

  // ── Claim helpers ──────────────────────────────────────
  isClaimSelected(group: FilterGroup, nIid: any): boolean {
    return group.claimBadges.some((b) => b.nIid === nIid);
  }

  addClaimBadge(group: FilterGroup, item: any) {
    if (!item) return;
    if (!group.claimBadges.find((b) => b.nIid === item.nIid)) {
      group.claimBadges = [...group.claimBadges, item];
      group.jClaims = group.claimBadges.map((b) => b.nIid);
    }
    setTimeout(() => { group.resetSelect = null; }, 10);
    this.cdr.detectChanges();
  }

  removeClaimBadge(group: FilterGroup, item: any) {
    group.claimBadges = group.claimBadges.filter((b) => b.nIid !== item.nIid);
    group.jClaims = group.claimBadges.map((b) => b.nIid);
    this.cdr.detectChanges();
  }

  // ── Contact helpers ────────────────────────────────────
  isContactSelected(group: FilterGroup, nContactid: any): boolean {
    return group.contactBadges.some((c) => c.nContactid === nContactid);
  }

  addContactBadge(group: FilterGroup, item: any) {
    if (!item) return;
    if (!group.contactBadges.find((c) => c.nContactid === item.nContactid)) {
      group.contactBadges = [...group.contactBadges, item];
      group.jContacts = group.contactBadges.map((c) => c.nContactid);
    }
    setTimeout(() => { group.resetContactSelect = null; }, 10);
    this.cdr.detectChanges();
  }

  removeContactBadge(group: FilterGroup, contact: any) {
    group.contactBadges = group.contactBadges.filter((c) => c.nContactid !== contact.nContactid);
    group.jContacts = group.contactBadges.map((c) => c.nContactid);
    this.cdr.detectChanges();
  }

  // ── File type helpers ──────────────────────────────────
  isFileTypeSelected(group: FilterGroup, nValue: number): boolean {
    return group.fileTypeBadges.some((f) => f.nValue === nValue);
  }

  addFileTypeBadge(group: FilterGroup, item: codeData) {
    if (!item) return;
    if (!group.fileTypeBadges.find((f) => f.nValue === item.nValue)) {
      group.fileTypeBadges = [...group.fileTypeBadges, item];
      group.jFiletypes = group.fileTypeBadges.map((f) => f.nValue);
    }
    setTimeout(() => { group.resetFileTypeSelect = null; }, 10);
    this.cdr.detectChanges();
  }

  removeFileTypeBadge(group: FilterGroup, item: codeData) {
    group.fileTypeBadges = group.fileTypeBadges.filter((f) => f.nValue !== item.nValue);
    group.jFiletypes = group.fileTypeBadges.map((f) => f.nValue);
    this.cdr.detectChanges();
  }

  // ── Generic badge helpers ──────────────────────────────
  addBadge(group: FilterGroup, item: any, badgesKey: keyof FilterGroup, idsKey: keyof FilterGroup, resetKey: keyof FilterGroup, idField: string) {
    if (!item) return;
    const badges: any[] = group[badgesKey] as any[];
    if (!badges.find((b: any) => b[idField] === item[idField])) {
      (group[badgesKey] as any[]) = [...badges, item];
      (group[idsKey] as any[]) = (group[badgesKey] as any[]).map((b: any) => b[idField]);
    }
    setTimeout(() => { (group as any)[resetKey] = null; }, 10);
    this.cdr.detectChanges();
  }

  removeBadgeItem(group: FilterGroup, item: any, badgesKey: keyof FilterGroup, idsKey: keyof FilterGroup, idField: string) {
    (group[badgesKey] as any[]) = (group[badgesKey] as any[]).filter((b: any) => b[idField] !== item[idField]);
    (group[idsKey] as any[]) = (group[badgesKey] as any[]).map((b: any) => b[idField]);
    this.cdr.detectChanges();
  }

  isSelectedIn(group: FilterGroup, badgesKey: keyof FilterGroup, item: any, idField: string): boolean {
    return (group[badgesKey] as any[]).some((b: any) => b[idField] === item[idField]);
  }

  handleFactLevel(group: FilterGroup, level: 'M' | 'S') {
    group.cType = level;
    this.cdr.detectChanges();
  }

  handleFactDateChange(group: FilterGroup, e: any) {
    if (group.selecteddatetype === 2) {
      const [start, end] = e;
      if (!start || !end) return;
      group.createDate = { start, end };
    } else {
      group.createDate = { start: e, end: e };
    }
    this.cdr.detectChanges();
  }

  async submit() {
    if (this.frm.invalid) {
      this.frm.markAllAsTouched();
      this.cdr.detectChanges();
      return;
    }
    if (this.isLoading) return;

    const v = this.frm.value;

    const jPages: number[] = [];
    if (v.cPageRange === 'R' && v.nPageFrom && v.nPageTo) {
      for (let i = v.nPageFrom; i <= v.nPageTo; i++) jPages.push(i);
    }

    // Map UI annotation type values to backend-expected values
    const annotTypeMap: Record<string, string> = { 'QMARK': 'QM', 'QFACT': 'QF' };
    const cAnnotationType = annotTypeMap[v.cAnnotationType] ?? v.cAnnotationType;

    // Derive legacy per-type flags from the annotation filter selection. The backend's
    // legacy export SP keys off bQmark / bQfact / bFact rather than the newer
    // cAnnotationType field, so non-doclink types silently dropped out unless these were
    // set. Spec: when bAnnotations is on with no specific filter ('ALL'), include every
    // supported type. When a specific filter is chosen, send only that type's flag.
    //
    // Doclinks (LINK) are gated on the backend by cAnnotationType (already in the payload
    // as `cAnnotationType` below) — no separate boolean flag is sent because the backend
    // DTO doesn't whitelist one.
    const annotsOn = !!v.bAnnotations;
    const allTypes = annotsOn && v.cAnnotationType === 'ALL';
    const bQmark = annotsOn && (allTypes || v.cAnnotationType === 'QMARK');
    const bQfact = annotsOn && (allTypes || v.cAnnotationType === 'QFACT');
    const bFact  = annotsOn && (allTypes || v.cAnnotationType === 'FACT');

    const mdl = {
      cExportName:        v.cExportName,
      cCasename:          this.current_session?.cName,
      cUsername:          this.userdetail ? `${this.userdetail.cFname} ${this.userdetail.cLname}` : '',
      nCaseid:            this.current_session?.nCaseid,
      nSessionid:         this.nSesid || this.current_session?.nSesid,
      nSesid:             this.nSesid || this.current_session?.nSesid,
      nUserid:            this.nUserid,
      cIsDemo:            this.cIsDemo,
      cTranscript:        this.current_session?.isTrans ? 'Y' : 'N',
      bCoverpg:           v.bCover,
      bAnnotations:       v.bAnnotations,
      bTimestamp:         v.bTimestamp,
      bWordIndex:         v.bWordIndex,
      cLayout:            v.cLayout,
      cPages:             v.cPageRange,
      jPages,
      cAnnotations:       v.cAnnotations,
      cAnnotationType,
      bAnnotationSummary: v.bAnnotationSummary,
      // Legacy SP fields required by backend — derived from cAnnotationType above.
      bQmark, cQMsize: 'S', bQfact, cQFsize: 'S',
      bFact, cFsize: 'S',
      cOrientation: 'A', bFitpg: true,
      cPgsize: 'A4', bPagination: true, bAdvanced: false,
      jIssues: [], jHIssues: [], jFIssues: [],
      // Filter groups — each group uses markNavjFilters-compatible field names
      jAnnotationFilters: this.filterGroups.map((g) => ({
        cFilterType:   g.value,
        cCategory:     g.cCategory,
        // Claim
        jClaims:       g.jClaims,
        // Issue
        jIssues:       g.jIssues,
        jRels:         g.jRels,
        jImps:         g.jImps,
        IsNote:        g.IsNote,
        IsFactlink:    g.IsFactlink,
        IsComment:     g.IsComment,
        // Fact
        jDate:         g.jDate,
        jFiletypes:    g.jFiletypes,
        createDate:    g.createDate,
        cType:         g.cType,
        // Contact
        jContacts:     g.jContacts,
        jCRoles:       g.jCRoles,
        jCPartys:      g.jCPartys,
        jCCompanies:   g.jCCompanies,
        IsContactNote: g.IsContactNote,
        // Task
        jTasks:        g.jTasks,
        jTShared:      g.jTShared,
        jTStatus:      g.jTStatus,
        jTPriority:    g.jTPriority,
        dTDate:        g.dTDate,
        IsTaskDesc:    g.IsTaskDesc,
      })),
    };

    this.isLoading = true;
    this.cdr.detectChanges();

    const res: any = await this.issueService.exportAnnotIssueHighlight(mdl);

    this.isLoading = false;
    this.cdr.detectChanges();

    if (res?.msg == 1) {
      this.tost.openSnackBar('Transcript exported successfully');
      this.downloadExport(res.path);
    } else {
      this.tost.openSnackBar('Failed to export transcript', 'E');
    }
  }

  private downloadExport(path: string) {
    const fileUrl = `${this.downloadPath}${path}?id=${Math.random()}`;
    this.issueService.downloadFile(fileUrl).subscribe({
      next: (blob) => {
        this.dialogRef.close();
        const a = document.createElement('a');
        const objectUrl = URL.createObjectURL(blob);
        a.href = objectUrl;
        a.download = `${this.frm.value.cExportName || 'transcript'}.pdf`;
        a.click();
        URL.revokeObjectURL(objectUrl);
      },
      error: () => this.tost.openSnackBar('Failed to download file', 'E'),
    });
  }

  cancel() {
    this.dialogRef.close();
  }
}
