// virtual-visible.directive.ts
import {
    Directive, Host, Input, OnChanges, SimpleChanges
} from '@angular/core';
import { AnnotationLayerComponent } from '../components/feeds/rt-components/layers/annotation-layer/annotation-layer.component';
import { ListRange } from '@angular/cdk/collections';

@Directive({
    selector: '[appCallOnVisible]',
    standalone: true
})
export class CallOnVisibleDirective implements OnChanges {
    @Input() activeRange!: ListRange;
    @Input() pageIndex!: number; // The current page's index
    
    private wasVisible = false;

    constructor(
        @Host() private hostCmp: AnnotationLayerComponent,
    ) { }

    ngOnChanges(changes: SimpleChanges): void {
        if (changes['activeRange'] || changes['pageIndex']) {
            this.checkVisibility();
        }
    }

    private checkVisibility(): void {
        if (!this.activeRange || this.pageIndex === undefined) return;
        
        const isCurrentlyVisible = this.pageIndex >= this.activeRange.start && 
                                   this.pageIndex < this.activeRange.end;
        
        // Only trigger onVisible when transitioning from not visible to visible
        if (isCurrentlyVisible && !this.wasVisible) {
            this.hostCmp.onVisible?.();
        }
        
        this.wasVisible = isCurrentlyVisible;
    }
}