// variable-height-virtual-scroll-strategy.ts
import { ListRange } from '@angular/cdk/collections';
import { CdkVirtualScrollViewport, VirtualScrollStrategy } from '@angular/cdk/scrolling';
import { Injectable } from '@angular/core';
import { Observable, Subject } from 'rxjs';
import { distinctUntilChanged } from 'rxjs/operators';

export interface VariableHeightItem {
  height?: number;
  estimatedHeight?: number;
  [key: string]: any;
}

@Injectable()
export class VariableHeightVirtualScrollStrategy implements VirtualScrollStrategy {
  private viewport!: CdkVirtualScrollViewport;
  private contentHeight = 0;
  private itemHeights: number[] = [];
  private itemPositions: number[] = [];
  private renderedRange: ListRange = { start: 0, end: 0 };
  // Default estimated height for items before they are rendered
  private defaultEstimatedHeight = 684;
  
  // Buffer for rendering extra items outside the visible area
  private bufferSize = 5;

  // Public property required by VirtualScrollStrategy interface
  public scrolledIndexChange = new Subject<number>();

  attach(viewport: CdkVirtualScrollViewport): void {
    this.viewport = viewport;
    this.updateRenderedRange();
  }

  detach(): void {
    this.scrolledIndexChange.complete();
  }

  onContentScrolled(): void {
    this.updateRenderedRange();
  }

  onDataLengthChanged(): void {
    this.updateItemHeights();
    this.updateContentHeight();
    this.updateRenderedRange();
  }

  onContentRendered(): void {
    this.measureRenderedItems();
    this.updateContentHeight();
    this.updateRenderedRange();
  }

  onRenderedOffsetChanged(): void {
    // Implementation if needed
  }

  scrollToIndex(index: number, behavior?: ScrollBehavior): void {
    if (!this.viewport) return;

    const offset = this.getOffsetForIndex(index);
    this.viewport.scrollToOffset(offset, behavior);
  }

  /**
   * Set estimated height for an item at a specific index
   */
  setEstimatedHeight(index: number, height: number): void {
    if (!this.itemHeights[index]) {
      this.itemHeights[index] = height;
      this.updateItemPositions();
    }
  }

  /**
   * Set actual height for an item at a specific index
   */
  setItemHeight(index: number, height: number): void {
    if (this.itemHeights[index] !== height) {
      this.itemHeights[index] = height;
      this.updateItemPositions();
      this.updateContentHeight();
    }
  }

  private updateItemHeights(): void {
    const dataLength = this.viewport.getDataLength();
    
    // Initialize heights array if needed
    if (this.itemHeights.length !== dataLength) {
      const newHeights = new Array(dataLength);
      
      // Copy existing heights
      for (let i = 0; i < Math.min(this.itemHeights.length, dataLength); i++) {
        newHeights[i] = this.itemHeights[i];
      }
      
      // Set default estimated height for new items
      for (let i = this.itemHeights.length; i < dataLength; i++) {
        newHeights[i] = this.defaultEstimatedHeight;
      }
      
      this.itemHeights = newHeights;
    }
    
    this.updateItemPositions();
  }

  private updateItemPositions(): void {
    this.itemPositions = [];
    let position = 0;
    
    for (let i = 0; i < this.itemHeights.length; i++) {
      this.itemPositions[i] = position;
      position += this.itemHeights[i] || this.defaultEstimatedHeight;
    }
  }

  private updateContentHeight(): void {
    const dataLength = this.viewport.getDataLength();
    this.contentHeight = dataLength > 0 ? 
      this.itemPositions[dataLength - 1] + (this.itemHeights[dataLength - 1] || this.defaultEstimatedHeight) : 0;
    
    this.viewport.setTotalContentSize(this.contentHeight);
  }

  private updateRenderedRange(): void {
    if (!this.viewport) return;

    const viewportSize = this.viewport.getViewportSize();
    const scrollOffset = this.viewport.measureScrollOffset();
    const dataLength = this.viewport.getDataLength();

    if (dataLength === 0) {
      this.renderedRange = { start: 0, end: 0 };
      this.viewport.setRenderedRange({ start: 0, end: 0 });
      return;
    }

    // Find the first visible item
    const startIndex = this.findIndexAtOffset(scrollOffset);
    
    // Find the last visible item
    const endIndex = this.findIndexAtOffset(scrollOffset + viewportSize);

    // Apply buffer
    const bufferedStart = Math.max(0, startIndex - this.bufferSize);
    const bufferedEnd = Math.min(dataLength, endIndex + this.bufferSize);

    this.renderedRange = { start: bufferedStart, end: bufferedEnd };
    
    // Set the rendered content offset
    const offsetToStart = this.getOffsetForIndex(bufferedStart);
    this.viewport.setRenderedContentOffset(offsetToStart);
    
    // Set the rendered range
    this.viewport.setRenderedRange(this.renderedRange);
    
    // Emit scrolled index change
    this.scrolledIndexChange.next(startIndex);
  }

  private findIndexAtOffset(offset: number): number {
    if (this.itemPositions.length === 0) return 0;
    
    // Binary search for the index
    let start = 0;
    let end = this.itemPositions.length - 1;
    
    while (start < end) {
      const mid = Math.floor((start + end) / 2);
      if (this.itemPositions[mid] <= offset) {
        start = mid + 1;
      } else {
        end = mid;
      }
    }
    
    return Math.max(0, start - 1);
  }

  getOffsetForIndex(index: number): number {
    if (index < 0 || index >= this.itemPositions.length) {
      return 0;
    }
    return this.itemPositions[index];
  }

  private zoomLevel = 1;

  setZoomLevel(level: number) {
    this.zoomLevel = level;
    // We might want to force a remeasure here, but usually checkViewportSize from component does it.
  }

  private measureRenderedItems(): void {
    if (!this.viewport) return;

    const renderedElements = this.viewport.elementRef.nativeElement
      .querySelectorAll('.cdk-virtual-scroll-content-wrapper > *');

    renderedElements.forEach((element: Element, i: number) => {
      const index = this.renderedRange.start + i;
      const height = element.getBoundingClientRect().height / this.zoomLevel;

      if (height > 0 && this.itemHeights[index] !== height) {
        this.setItemHeight(index, height);
      }
    });
  }

  /**
   * Force re-measurement of rendered items and update content height and range.
   * Call this when viewport size changes (e.g. mini-split appears/disappears)
   * or when page content changes during live sessions.
   */
  forceRemeasure(): void {
    if (!this.viewport) return;
    this.measureRenderedItems();
    this.updateContentHeight();
    this.updateRenderedRange();
  }

  /**
   * Returns the total content height (sum of all item heights).
   */
  getTotalContentHeight(): number {
    return this.contentHeight;
  }
}