import { AfterViewInit, Component, effect, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { hightlightModeType } from '../../interfaces/feed.interface';
import { AnnotsService } from '../../services/annots/annots.service';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
import { TranslateModule } from '@ngx-translate/core';
import { CommonModule } from '@angular/common';
import { SelectionActionsService, SelectionPrimaryMode } from '../../../shared/services/selection-actions/selection-actions.service';
import { SelectionActionsControlComponent } from '../../../shared/components/selection-actions/selection-actions-control.component';

@Component({
  selector: 'annot-box',
  standalone: true,
  imports: [CommonModule, MatMenuModule, TranslateModule, SelectionActionsControlComponent],
  templateUrl: './annot-box.component.html',
  styleUrl: './annot-box.component.scss'
})
export class AnnotBoxComponent implements AfterViewInit {

  @ViewChild(MatMenuTrigger) menuTrigger!: MatMenuTrigger;

  @Input() hightlightMode: hightlightModeType;
  @Output() hightlightModeChange: EventEmitter<hightlightModeType> = new EventEmitter<hightlightModeType>();

  @Input() visibleMarkNavModel: boolean = false;
  @Output() visibleMarkNavModelChange: EventEmitter<boolean> = new EventEmitter<boolean>();
  @Input() visibleIssueModel: boolean = false;
  @Output() visibleIssueModelChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() indexEnabled: boolean = false;
  @Output() indexEnabledChange: EventEmitter<boolean> = new EventEmitter<boolean>();
  @Output() annotClick: EventEmitter<void> = new EventEmitter<void>();

  /** Fires when the user has armed QFact-only rapid mode (no Fact, no
   *  DocLink, no Copy) AND has not requested note input via the toolbar's
   *  "Include note" / "Include selected text + note" checkboxes. The
   *  parent should auto-submit the QFact directly without opening the
   *  fact-creation form — that's the whole point of "rapid" mode.
   *
   *  We emit instead of routing through hightlightModeChange because the
   *  side-modal-manager's form is keyed on hightlightMode === 'QF' / 'F',
   *  so the moment we set 'QF' on the parent, the form opens. Bypass the
   *  mode flag entirely for the rapid path. */
  @Output() qfactRapidAutoSubmit: EventEmitter<void> = new EventEmitter<void>();

  /** Sibling of `qfactRapidAutoSubmit` for the QFact + Note rapid path.
   *  Same gate (single QF, not copy) but fired only when the user has
   *  ticked one of the toolbar's "with note" checkboxes. The parent
   *  opens a compact popup beside the highlight instead of the
   *  side-modal fact-creation. We bypass `hightlightMode='QF'` for the
   *  same reason `qfactRapidAutoSubmit` does — that mode flag opens
   *  the side-modal automatically. */
  @Output() qfactRapidNoteOpen: EventEmitter<void> = new EventEmitter<void>();


  /** Tracks the previous single-mode so the auto-fire effect can detect
   *  transitions (multi → single, or single A → single B). */
  private prevSingle: SelectionPrimaryMode | null = null;
  private firstStateRun: boolean = true;

  constructor(private readonly annotsService: AnnotsService, public selectionActions: SelectionActionsService) {
    // When the user changes the toolbar mode while text is still selected
    // (annot-box is mounted = selection is pending), close the popup and
    // auto-fire the corresponding action. Copy mode is excluded — copy
    // behaves on the next mouseup, not on the current selection.
    effect(() => {
      const single = this.selectionActions.singleKind();
      const isCopy = this.selectionActions.isCopy();

      if (this.firstStateRun) {
        this.firstStateRun = false;
        this.prevSingle = single;
        return;
      }

      const transitioned = single !== this.prevSingle || isCopy;
      this.prevSingle = single;

      if (!transitioned) return;
      if (!this.annotsService.isBoxEnabled()) return;

      // Close the popup regardless of which mode we transitioned to.
      this.menuTrigger?.closeMenu();

      // Fire the equivalent of clicking the popup's button — onHightlightModeChange
      // emits up to feed-display which routes to the existing fact / doclink flow.
      // QFact rapid + no notes: bypass the form (same logic as ngAfterViewInit).
      if (single && !isCopy) {
        if (single === 'QF' && !this.wantsNoteInput()) {
          this.annotsService.disableAnnotBox();
          this.qfactRapidAutoSubmit.emit();
          return;
        }
        if (single === 'QF' && this.wantsNoteInput()) {
          // QFact rapid + note: open the compact popup beside the highlight
          // instead of the side-modal fact-creation form. Emit BEFORE
          // disabling so the parent can capture annotBox.y while it's
          // still set — that's the only place the highlight's vertical
          // position is recorded for the rapid path.
          this.qfactRapidNoteOpen.emit();
          this.annotsService.disableAnnotBox();
          return;
        }
        this.onHightlightModeChange(single);
      }
    });
  }

  onHightlightModeChange(mode: hightlightModeType) {

    this.annotsService.disableAnnotBox();
    if (this.visibleMarkNavModel) {
      this.visibleMarkNavModel = false;
      this.visibleMarkNavModelChange.emit(this.visibleMarkNavModel);
    }
    if (this.visibleIssueModel) {
      this.visibleIssueModel = false;
      this.visibleIssueModelChange.emit(this.visibleIssueModel);
    }

    if (this.indexEnabled) {
      this.indexEnabled = false;
      this.indexEnabledChange.emit(this.indexEnabled);
    }

    this.hightlightMode = mode;
    this.hightlightModeChange.emit(mode);
    this.annotClick.emit();
  }

  ngAfterViewInit(): void {
    // Multi mode (≥2 of QF/F/D armed) → show the picker.
    // Single mode (exactly one armed) → skip the picker and fire that mode's
    // action directly, so the user doesn't have to click a one-button menu.
    // Copy / nothing armed → discard the temp annotation.
    setTimeout(() => {
      const multi = this.selectionActions.activeArr().length >= 2 && !this.selectionActions.isCopy();
      if (multi) {
        this.menuTrigger.openMenu();
        return;
      }
      if (this.selectionActions.isSingle()) {
        const single = this.selectionActions.singleKind();
        if (single) {
          // QFact rapid + no notes wanted: bypass the form entirely. The
          // parent auto-submits with the QFact panel's selected issues
          // (or the default Unassigned).
          if (single === 'QF' && !this.wantsNoteInput()) {
            this.annotsService.disableAnnotBox();
            this.qfactRapidAutoSubmit.emit();
            return;
          }
          // QFact rapid + note: open the compact popup beside the highlight.
          // Otherwise (Fact, DocLink) fall through to the form. Emit
          // BEFORE disabling so the parent can read annotBox.y while
          // it's still set (same reason as the effect path above).
          if (single === 'QF' && this.wantsNoteInput()) {
            this.qfactRapidNoteOpen.emit();
            this.annotsService.disableAnnotBox();
            return;
          }
          this.onHightlightModeChange(single);
          return;
        }
      }
      this.annotsService.disableAnnotBox();
      this.annotsService.removeTemp();
    }, 0);
  }

  /** True when the user has ticked one of the toolbar "with note" checkboxes
   *  — they want the fact-creation form to open so they can type a note. */
  private wantsNoteInput(): boolean {
    const s = this.selectionActions.state();
    return !!(s.qfIncludeNote || s.qfIncludeTextPlusNote);
  }

  onMenuClosed(event: any) {
    if (this.annotsService.isBoxEnabled()) {
      console.log('Menu closed!');
      // you can run your cleanup logic here
      this.annotsService.disableAnnotBox();
      this.annotsService.removeTemp();
    }
  }
}