import { Component, EventEmitter, Input, SimpleChanges, inject } from '@angular/core';
import { timestampPipe } from '../../../../pip/timestamp.pip';
import { NgClass, NgStyle } from '@angular/common';
import { HighlightPipe } from '../../../../pip/feed-line.pip';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { AnnotsService } from '../../../../services/annots/annots.service';
import { qMarksAnnots } from '../../../../interfaces/annotation.interface';
import { RtFactService } from '../../../../../shared/services/rt-fact/rt-fact.service';
import { SearchService } from '../../../../search/search.service';
import { activeFeedData, finalFeedData } from '../../../../interfaces/feed-display.interface';
import { realtimeEventParams } from '../../../../interfaces/realtime.interface';
import { MyfileService } from '../../../../../shared/services/myfile/myfile.service';

@Component({
  selector: 'feed-line',
  standalone: true,
  imports: [NgClass, NgStyle, timestampPipe, HighlightPipe],
  templateUrl: './feed-line.component.html',
  styleUrl: './feed-line.component.scss'
})
export class FeedLineComponent {

  private myfileService = inject(MyfileService);

  // Cache of cTab values already prefetched in this component lifetime so a
  // user dragging the cursor across multiple links doesn't fire the same
  // prefetch repeatedly. The MyfileService also caches by (case, tab) — this
  // is a per-component dedupe to avoid even calling into the service.
  private prefetchedTabs = new Set<string>();

  @Input() showTimestamp: boolean;
  @Input() isActiveFeed: boolean = false;
  @Input() lineIndex: number;
  @Input() line: finalFeedData;
  @Input() pageno: number;
  @Input() nCaseid: string;
  @Input() nUserid: string;
  @Input() qMarks: qMarksAnnots[] = [];
  @Input() activePageData: activeFeedData[];


  @Input() smallFeed: boolean;

  laoding: boolean = false;

  qMarkColor: string = '#EBCAFF';
  visible: boolean = true;
  @Input() realtimeEvent: EventEmitter<realtimeEventParams> = new EventEmitter<realtimeEventParams>();
  constructor(public readonly fds: FeedDisplayService, private rtFact: RtFactService, private readonly tost: TostbarService, private annotService: AnnotsService, public searchService: SearchService) {

  }
  ngOnInit(): void {
    this.checkForVisiblity()
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes["activePageData"] && !changes["activePageData"].firstChange) {
      this.checkForVisiblity()
    }
    if (changes["line"] && !changes["line"].firstChange) {
      this.checkForVisiblity()
    }
  }


  async highlightLine() {
    if (this.laoding || this.smallFeed) return;
    this.laoding = true;
    try {
      if (this.line.nHid) {
        await this.rtFact.deleteHyperlink({ nHid: this.line.nHid });
        this.annotService.deleteqMark(this.line.nHid);
        this.fds.emit('QMARK-DELETED', this.line.nHid)
        this.line.nHid = null;
        this.laoding = false;
        return
      }
      const mdl: any = {
        nCaseid: this.nCaseid,
        nSessionid: this.fds.sessionDetail?.nSesid,
        nUserid: this.nUserid,
        cNote: this.line.lines.join(''),
        cPageno: this.pageno.toString(),
        cLineno: (this.lineIndex).toString(),
        cTime: this.line.time,
        cTranscript: this.fds.sessionDetail?.isTrans ? 'Y' : 'N',
        oP: this.line.oPage || 0,
        oL: this.line.oLine || 0,
        identity: String(this.line.unicid || ''),
      };
      const res = await this.rtFact.insertHyperlink(mdl);
      if (res.length) {
        const qMark: qMarksAnnots = {
          nHid: res[0].nHid,
          cPageno: this.pageno,
          cLineno: this.lineIndex,
          cTime: this.line.time,
          cColor: res[0]?.cColor || this.qMarkColor,
          identity: String(this.line.unicid || '')
        }
        this.annotService.setqMark(qMark);
        this.line.nHid = res[0].nHid;
        this.fds.emit('QMARK-CREATED', qMark)
      }
    } catch (error) {
      console.log(error)
    }
    this.laoding = false;
  }


  checkForVisiblity() {
    if (this.activePageData?.length) {
      const pg = this.pageno;
      const ln = this.lineIndex;
      if (this.activePageData.findIndex(line => (line.index + 1) == ln && (line.page == pg)) > -1)
        this.visible = false;
      else
        this.visible = true;
    } else {
      this.visible = true;
    }
  }



  clickOnTabs(e: any) {

    try {
      if (e.target.classList.contains('clickable-word')) {
        e.stopPropagation(); // Prevent bubbling to parent's (click)="this.ispdfactive=false"
        const value = e.target.innerText.replace(/[{}]/g, '');
        const tab = value.split('-')[0];
        let page = 1;
        if (value.includes("-")) {
          page = parseInt(value.split('-')[1]);
        }
        this.realtimeEvent.next({ type: 'HYPERLINK-CLICK', data: { cTab: tab, nPageno: page } })
      }
    } catch (error) {
      console.error(error);
    }

  }

  /** Warm the filedata cache when the cursor enters a `.clickable-word` so the
   *  click that follows skips the API roundtrip. Mouseover bubbles every time
   *  the cursor crosses a child element, so we dedupe per cTab. */
  onHoverHyperlink(e: any): void {
    try {
      const target = e?.target as HTMLElement | undefined;
      if (!target || !target.classList?.contains('clickable-word')) return;
      const value = (target.innerText || '').replace(/[{}]/g, '').trim();
      if (!value) return;
      const tab = value.split('-')[0];
      if (!tab || this.prefetchedTabs.has(tab)) return;
      this.prefetchedTabs.add(tab);
      // Fire and forget. Errors are already surfaced inside MyfileService.
      this.myfileService.getFiledata({ cTab: tab, nCaseid: this.nCaseid } as any)
        .catch(() => { /* non-critical */ });
    } catch {
      // non-critical
    }
  }



}
